package com.smartbanksorter;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TabSprites;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * The category tabs in Bank Tags' tag tab strip, mixed with the user's tag tabs so one strip holds both and they
 * can be dragged into one order.
 * <p>
 * Bank Tags draws every tab in its TabManager's list each time the bank is built, so the category tabs go in that
 * list, in memory only. Bank Tags' widgets for them get the sorter's op and listener in place of Bank Tags' own
 * (view, rename, delete...), so Bank Tags never opens a category tab as a tag, and drags that involve a category
 * tab are handled here before Bank Tags sees them. Bank Tags saves its whole list to its own settings whenever the
 * user changes a tag tab; the category tabs are taken straight back out of what it saved, and the mixed order kept
 * in the sorter's settings instead.
 */
@Slf4j
class BankTagsStrip
{
	// Bank Tags' scroll catcher, arrows and new-tab button come before its tabs in the item container.
	private static final int TAGTAB_CHILD_OFFSET = 4;
	// Bank Tags' "Use tag tabs" setting. Not a public constant there, unlike its group and tab list keys.
	private static final String BANK_TAGS_USE_TABS = "useTabs";
	// Starts a category tab's tag in Bank Tags' list. Bank Tags won't let a tag name have it, so a category tab
	// can't share its tag (or the icon setting saved under it) with one of the user's tag tabs, whatever its name.
	// Not ':', which Bank Tags also refuses: ConfigManager refuses it in a key, and Bank Tags saves an icon setting
	// for every tab in its list.
	private static final String MARK = "/";

	private final Client client;
	private final ClientThread clientThread;
	private final SmartBankSorterConfig config;
	private final ConfigManager configManager;
	private final TabManager tabManager;
	private final TagManager tagManager;
	private final BooleanSupplier bankTagsOn;
	// The category the plugin currently filters to (null = all), and what to do when a tab is clicked.
	private final Supplier<String> activeTag;
	private final Supplier<String> focused;
	private final Consumer<String> onFocus;
	private final Runnable rebuildBank;
	// Our tabs in Bank Tags' list, by tag. The same objects go back in the list on every build, so they are told
	// from the user's tag tabs by identity: TagTab's equals is by name.
	private final Map<String, TagTab> ourTabs = new LinkedHashMap<>();
	// The widgets Bank Tags drew for our tabs and patch() took over, which then carry the category's name.
	private final Map<Widget, TagTab> patched = new IdentityHashMap<>();
	// The tag tabs and category tabs together, as last arranged; what the strip is rebuilt to on each bank open.
	private List<String> order = new ArrayList<>();
	// The strip as it was last put together, every tab in order.
	private List<String> drawn = Collections.emptyList();
	// The category tabs the last layout wanted, with their icons, and what the strip was last synced to.
	private List<String> lastTabs = Collections.emptyList();
	private List<Integer> lastIcons = Collections.emptyList();
	private List<String> syncedTabs = Collections.emptyList();
	private boolean rebuildQueued;
	// The layout Bank Tags last removed, the tag it was under, and the client cycle it went in.
	private String removedLayoutTag;
	private String removedLayout;
	private int removedLayoutCycle;

	BankTagsStrip(Client client, ClientThread clientThread, SmartBankSorterConfig config, ConfigManager configManager,
		TabManager tabManager, TagManager tagManager, BooleanSupplier bankTagsOn, Supplier<String> activeTag,
		Supplier<String> focused, Consumer<String> onFocus, Runnable rebuildBank)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.configManager = configManager;
		this.tabManager = tabManager;
		this.tagManager = tagManager;
		this.bankTagsOn = bankTagsOn;
		this.activeTag = activeTag;
		this.focused = focused;
		this.onFocus = onFocus;
		this.rebuildBank = rebuildBank;
	}

	void loadOrder(String saved)
	{
		order = new ArrayList<>(Text.fromCSV(saved));
	}

	/**
	 * Whether the category tabs go in Bank Tags' strip: they're on, and Bank Tags is on with its tag tabs.
	 */
	boolean active()
	{
		return config.enabled() && config.categoryTabs() && bankTagsOn.getAsBoolean()
			&& !"false".equals(configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, BANK_TAGS_USE_TABS));
	}

	/**
	 * Puts the category tabs in Bank Tags' list, in the arranged order, right before Bank Tags draws the strip from
	 * it. Bank Tags reloads the list from its settings whenever the bank opens, so this runs on every build.
	 */
	void sync()
	{
		List<TagTab> list = tabManager.getTabs();
		list.removeIf(this::isOurs);
		if (!active())
		{
			ourTabs.clear();
			syncedTabs = Collections.emptyList();
			return;
		}
		List<TagTab> mine = new ArrayList<>();
		for (int i = 0; i < lastTabs.size(); i++)
		{
			TagTab tab = ourTabs.computeIfAbsent(MARK + lastTabs.get(i), tag ->
			{
				TagTab t = new TagTab();
				t.setTag(tag);
				return t;
			});
			tab.setIconItemId(lastIcons.get(i));
			mine.add(tab);
		}
		ourTabs.values().removeIf(t -> !mine.contains(t));
		syncedTabs = lastTabs;
		List<TagTab> merged = merge(order, new ArrayList<>(list), mine);
		list.clear();
		list.addAll(merged);
		drawn = new ArrayList<>();
		merged.forEach(t -> drawn.add(t.getTag()));
	}

	/**
	 * The strip in the arranged order: the user's tag tabs in Bank Tags' own order, with each category tab put
	 * back where it was. A tab the order doesn't know goes at the end. Tag tabs the user reordered while the
	 * sorter was off keep Bank Tags' order; the category tabs follow the tag tab they came after.
	 */
	static List<TagTab> merge(List<String> order, List<TagTab> tagTabs, List<TagTab> categoryTabs)
	{
		List<TagTab> out = new ArrayList<>();
		Deque<TagTab> tagsLeft = new ArrayDeque<>(tagTabs);
		List<TagTab> categoriesLeft = new ArrayList<>(categoryTabs);
		for (String name : order)
		{
			TagTab category = null;
			for (TagTab t : categoriesLeft)
			{
				if (t.getTag().equals(name))
				{
					category = t;
					break;
				}
			}
			if (category != null)
			{
				out.add(category);
				categoriesLeft.remove(category);
			}
			else if (tagsLeft.stream().anyMatch(t -> sameTag(t, name)))
			{
				TagTab t;
				do
				{
					t = tagsLeft.poll();
					out.add(t);
				}
				while (!sameTag(t, name));
			}
		}
		out.addAll(tagsLeft);
		out.addAll(categoriesLeft);
		return out;
	}

	/**
	 * Takes over the widgets Bank Tags has just made for the category tabs: in its strip, and in its "View tag
	 * tabs" view, which draws every tab as an item. Clicking one shows that tab's categories; none of Bank Tags'
	 * tag tab ops apply.
	 */
	void patch()
	{
		// Bank Tags deletes the widgets it redraws.
		patched.keySet().removeIf(w -> !isChild(w));
		if (ourTabs.isEmpty())
		{
			return;
		}
		patchChildren(client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER), TAGTAB_CHILD_OFFSET);
		patchChildren(client.getWidget(InterfaceID.Bankmain.ITEMS), SmartBankSorterPlugin.BANK_SLOTS);
	}

	private void patchChildren(Widget parent, int from)
	{
		Widget[] children = parent == null ? null : parent.getChildren();
		if (children == null)
		{
			return;
		}
		boolean inStrip = parent.getId() == InterfaceID.Bankmain.ITEMS_CONTAINER;
		for (int i = from; i < children.length; i++)
		{
			Widget w = children[i];
			TagTab tab = w == null || w.getType() != WidgetType.GRAPHIC || w.getName() == null ? null
				: ourTabs.get(Text.removeTags(w.getName()));
			if (tab == null)
			{
				continue;
			}
			patched.put(w, tab);
			String category = category(tab);
			boolean active = category.equals(focused.get());
			boolean background = w.getSpriteId() == TabSprites.TAB_BACKGROUND.getSpriteId()
				|| w.getSpriteId() == TabSprites.TAB_BACKGROUND_ACTIVE.getSpriteId();
			if (background)
			{
				w.setSpriteId((active ? TabSprites.TAB_BACKGROUND_ACTIVE : TabSprites.TAB_BACKGROUND).getSpriteId());
			}
			// In the strip the ops sit on the background, under the icon; in the tag tab view the icon has them.
			if (background || !inStrip)
			{
				w.clearActions();
				w.setAction(0, active ? "Show all" : "Show");
				w.setHasListener(true);
				w.setOnOpListener((JavaScriptCallback) e -> onFocus.accept(category));
			}
			w.setName(ColorUtil.wrapWithColorTag(category, config.headerColor()));
		}
	}

	/**
	 * The category tabs the layout just drew, with their icons. The strip holds what the previous layout wanted,
	 * so a change to which tabs there are means one more build to put them in; a change of icon is applied on
	 * the spot.
	 */
	void update(List<String> tabs, List<Integer> icons)
	{
		lastTabs = tabs;
		lastIcons = icons;
		if (!tabs.equals(syncedTabs))
		{
			queueRebuild(false);
			return;
		}
		for (int i = 0; i < tabs.size(); i++)
		{
			TagTab tab = ourTabs.get(MARK + tabs.get(i));
			int icon = icons.get(i);
			if (tab != null && tab.getIconItemId() != icon)
			{
				tab.setIconItemId(icon);
				patched.forEach((w, t) ->
				{
					if (t == tab && w.getItemId() != -1)
					{
						w.setItemId(icon);
					}
				});
			}
		}
	}

	/**
	 * Rebuilds the bank on a later client tick, which has Bank Tags draw its strip from its list again and
	 * {@link #patch()} take the category tabs over again. Bank Tags queues a redraw of its own after some changes
	 * (a new icon, say), which would undo the patch: {@code afterBankTags} queues the rebuild behind it.
	 */
	private void queueRebuild(boolean afterBankTags)
	{
		if (rebuildQueued)
		{
			return;
		}
		rebuildQueued = true;
		Runnable rebuild = () ->
		{
			rebuildQueued = false;
			rebuildBank.run();
		};
		clientThread.invokeLater(afterBankTags ? () -> clientThread.invokeLater(rebuild) : rebuild);
	}

	/**
	 * A drag involving a category tab, seen before Bank Tags. Two tabs: the dragged one goes where the other is,
	 * the way Bank Tags inserts its own (after it when dragged down the strip), and the order is kept. Never a
	 * swap: the tag tab dropped on would move past other tag tabs, and Bank Tags reloads their order from its own
	 * settings on every bank open. A tag tab dragged onto a category tab does move past other tag tabs, so their
	 * new order goes to Bank Tags' settings, as Bank Tags itself writes it after a reorder; nothing else of the
	 * sorter's goes there. Anything dropped on a category tab: nothing, where Bank Tags would tag the item with the
	 * tab's name. Either way the drop target is cleared so Bank Tags and the game leave it alone.
	 */
	void onDragBefore()
	{
		Widget dragged = client.getDraggedWidget();
		Widget draggedOn = client.getDraggedOnWidget();
		if (ourTabs.isEmpty() || dragged == null || draggedOn == null || client.getMouseCurrentButton() != 0)
		{
			return;
		}
		TagTab from = tabAt(dragged);
		TagTab to = tabAt(draggedOn);
		if (!isOurs(from) && !isOurs(to))
		{
			return;
		}
		client.setDraggedOnWidget(null);
		if (from == null || to == null || from == to)
		{
			return;
		}
		List<TagTab> list = tabManager.getTabs();
		int i = indexOf(list, from);
		int j = indexOf(list, to);
		if (i < 0 || j < 0)
		{
			return;
		}
		List<String> tagTabsBefore = tagTabNames(list);
		list.add(j, list.remove(i));
		saveOrder(list);
		List<String> tagTabsAfter = tagTabNames(list);
		if (!tagTabsAfter.equals(tagTabsBefore))
		{
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tagTabsAfter));
		}
		queueRebuild(false);
	}

	/**
	 * The user's tag tabs in the list, in order.
	 */
	private List<String> tagTabNames(List<TagTab> list)
	{
		List<String> names = new ArrayList<>();
		for (TagTab t : list)
		{
			if (!isOurs(t))
			{
				names.add(t.getTag());
			}
		}
		return names;
	}

	/**
	 * After Bank Tags has seen a drop: it redraws its strip after some, with its own ops on our tabs again.
	 */
	void onDragAfter()
	{
		if (client.getMouseCurrentButton() == 0)
		{
			patch();
		}
	}

	/**
	 * The tab a widget stands for: one of the pairs Bank Tags draws in its strip, or one of the items in its
	 * "View tag tabs" view.
	 */
	private TagTab tabAt(Widget w)
	{
		Widget parent = w.getParent();
		if (parent == null || w.getName() == null)
		{
			return null;
		}
		boolean inStrip = parent.getId() == InterfaceID.Bankmain.ITEMS_CONTAINER && w.getIndex() >= TAGTAB_CHILD_OFFSET;
		boolean inTagTabTab = parent.getId() == InterfaceID.Bankmain.ITEMS && w.getIndex() >= SmartBankSorterPlugin.BANK_SLOTS;
		if (!inStrip && !inTagTabTab)
		{
			return null;
		}
		TagTab ours = patched.get(w);
		if (ours != null)
		{
			return ours;
		}
		String name = Text.removeTags(w.getName());
		for (TagTab t : tabManager.getTabs())
		{
			if (t.getTag().equals(name))
			{
				return t;
			}
		}
		return null;
	}

	/**
	 * Bank Tags saves its whole tab list, category tabs included, after any change to a tag tab. Keeps the mixed
	 * order the list is in and puts Bank Tags' settings back without the category tabs, in the same call, so they
	 * are never left there.
	 */
	void onConfigChanged(ConfigChanged event)
	{
		if (!BankTagsPlugin.CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}
		String key = event.getKey();
		if (key.startsWith(BankTagsPlugin.TAG_LAYOUT_PREFIX) && event.getNewValue() == null)
		{
			// A rename removes the old layout before saving the tab list; kept in case the rename stops there.
			removedLayoutTag = key.substring(BankTagsPlugin.TAG_LAYOUT_PREFIX.length());
			removedLayout = event.getOldValue();
			removedLayoutCycle = client.getGameCycle();
			return;
		}
		if (ourTabs.isEmpty() || event.getNewValue() == null)
		{
			return;
		}
		if (BankTagsPlugin.TAG_TABS_CONFIG.equals(key))
		{
			List<String> saved = Text.fromCSV(event.getNewValue());
			if (saved.stream().noneMatch(ourTabs::containsKey))
			{
				return;
			}
			String[] rename = rename(drawn, saved);
			if (rename != null && activeTag.get() == null)
			{
				// Bank Tags' rename throws with no tag tab open (activeTag.equals), right after this save: the
				// items' tags and the layout would stay under the old name. It removes the layout in the same
				// cycle; one removed earlier (Disable layout) stays removed.
				String layout = removedLayoutCycle == client.getGameCycle()
					&& Text.standardize(rename[0]).equals(removedLayoutTag) ? removedLayout : null;
				clientThread.invokeLater(() -> finishRename(rename[0], rename[1], layout));
			}
			order = keepRenamedInPlace(drawn, saved);
			if (!order.equals(saved))
			{
				reorderList(order);
			}
			configManager.setConfiguration(SmartBankSorterConfig.GROUP, SmartBankSorterConfig.TAB_ORDER_KEY, Text.toCSV(order));
			List<String> tagTabs = new ArrayList<>(order);
			tagTabs.removeAll(ourTabs.keySet());
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tagTabs));
			// Bank Tags redraws its strip after saving, with its own ops on the category tabs again.
			queueRebuild(true);
		}
		else if (key.startsWith(BankTagsPlugin.TAG_ICON_PREFIX))
		{
			String tag = key.substring(BankTagsPlugin.TAG_ICON_PREFIX.length());
			if (ourTabs.keySet().stream().anyMatch(name -> Text.standardize(name).equals(tag)))
			{
				configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, key);
			}
		}
	}

	/**
	 * Bank Tags renames a tag tab by taking it out of its list and adding it back at the end. With exactly one name
	 * gone and one new, and the rest in the same order, that's a rename: the tab stays where it was.
	 */
	static List<String> keepRenamedInPlace(List<String> before, List<String> after)
	{
		String[] rename = rename(before, after);
		if (rename == null)
		{
			return new ArrayList<>(after);
		}
		List<String> renamed = new ArrayList<>(before);
		renamed.set(before.indexOf(rename[0]), rename[1]);
		return renamed;
	}

	/**
	 * @return the old and new name if {@code after} is {@code before} with one tab renamed as Bank Tags does it,
	 * otherwise null
	 */
	static String[] rename(List<String> before, List<String> after)
	{
		List<String> added = new ArrayList<>(after);
		added.removeAll(before);
		List<String> removed = new ArrayList<>(before);
		removed.removeAll(after);
		if (added.size() != 1 || removed.size() != 1)
		{
			return null;
		}
		List<String> rest = new ArrayList<>(after);
		rest.removeAll(added);
		List<String> restBefore = new ArrayList<>(before);
		restBefore.removeAll(removed);
		return rest.equals(restBefore) ? new String[]{removed.get(0), added.get(0)} : null;
	}

	/**
	 * The rest of Bank Tags' rename, which it didn't get to: the items' tags, and the layout, under the new name.
	 */
	private void finishRename(String oldTag, String newTag, String layout)
	{
		tagManager.renameTag(oldTag, newTag);
		if (layout != null)
		{
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP,
				BankTagsPlugin.TAG_LAYOUT_PREFIX + Text.standardize(newTag), layout);
		}
		queueRebuild(false);
	}

	// Bank Tags redraws its strip from its list right after saving it.
	private void reorderList(List<String> names)
	{
		List<TagTab> list = tabManager.getTabs();
		List<TagTab> sorted = new ArrayList<>(list);
		sorted.sort(Comparator.comparingInt(t -> names.indexOf(t.getTag())));
		list.clear();
		list.addAll(sorted);
	}

	/**
	 * Takes the category tabs out of Bank Tags' list, for when the plugin stops.
	 */
	void remove()
	{
		tabManager.getTabs().removeIf(this::isOurs);
		ourTabs.clear();
		patched.clear();
		drawn = Collections.emptyList();
		lastTabs = Collections.emptyList();
		lastIcons = Collections.emptyList();
		syncedTabs = Collections.emptyList();
	}

	private void saveOrder(List<TagTab> list)
	{
		order = new ArrayList<>();
		list.forEach(t -> order.add(t.getTag()));
		configManager.setConfiguration(SmartBankSorterConfig.GROUP, SmartBankSorterConfig.TAB_ORDER_KEY, Text.toCSV(order));
	}

	// Bank Tags keeps a tag as typed until it next loads its tabs from its settings, lowercased.
	private static boolean sameTag(TagTab tab, String name)
	{
		return Text.standardize(tab.getTag()).equals(Text.standardize(name));
	}

	private static String category(TagTab tab)
	{
		return tab.getTag().substring(MARK.length());
	}

	private static boolean isChild(Widget w)
	{
		Widget parent = w.getParent();
		Widget[] children = parent == null ? null : parent.getChildren();
		return children != null && w.getIndex() < children.length && children[w.getIndex()] == w;
	}

	private boolean isOurs(TagTab tab)
	{
		return tab != null && ourTabs.get(tab.getTag()) == tab;
	}

	private static int indexOf(List<TagTab> list, TagTab tab)
	{
		for (int i = 0; i < list.size(); i++)
		{
			if (list.get(i) == tab)
			{
				return i;
			}
		}
		return -1;
	}
}

package com.smartbanksorter;

import java.util.Arrays;
import java.util.List;

/**
 * Built-in category names, in their default display order.
 */
final class Categories
{
	static final String CURRENCY = "Currency";
	static final String MELEE = "Melee";
	static final String RANGED = "Ranged";
	static final String MAGIC = "Magic";
	static final String SLAYER = "Slayer";
	static final String JEWELLERY = "Jewellery";
	static final String AMMO = "Ammo";
	static final String RUNES = "Runes";
	static final String TELEPORTS = "Teleports";
	static final String POTIONS = "Potions";
	static final String FOOD = "Food";
	static final String PRAYER = "Prayer";
	static final String TOOLS = "Tools";
	static final String HERBLORE = "Herblore";
	static final String FARMING = "Farming";
	// Materials go to the skill that uses them.
	static final String ORES_BARS = "Smithing";
	static final String GEMS = "Crafting";
	static final String LOGS = "Fletching";
	static final String PLANKS = "Construction";
	static final String PYRE_LOGS = "Firemaking";
	static final String CLUES = "Clues";
	static final String QUEST = "Quest";
	static final String COSMETIC = "Cosmetic";
	static final String OTHER_GEAR = "Other gear";
	static final String MISC = "Misc";

	static final List<String> COMBAT_STYLES = Arrays.asList(MELEE, RANGED, MAGIC);

	static final List<String> DEFAULT_ORDER = Arrays.asList(
		CURRENCY, MELEE, RANGED, MAGIC, SLAYER, AMMO, RUNES, TELEPORTS, POTIONS, FOOD, PRAYER,
		"Mining", "Smithing", "Fishing", "Cooking", "Woodcutting", "Firemaking", "Fletching", "Crafting",
		HERBLORE, FARMING, "Hunter", "Construction", "Agility", "Thieving", "Runecraft", "Sailing",
		// Jewellery left here has no combat or teleport use (those go to the styles / Teleports).
		TOOLS, CLUES, QUEST, JEWELLERY, COSMETIC, OTHER_GEAR, MISC
	);

	private Categories()
	{
	}
}

package com.smartbanksorter;

import static com.smartbanksorter.Categories.*;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Decides an item's category. Equipment is classified from its combat stats rather than its name,
 * everything else from its inventory actions (Eat, Drink, Bury, Break...) and then a few name rules.
 */
final class Categoriser
{
	private static final Set<String> TOOLS_EXACT = new HashSet<>(Arrays.asList(
		"hammer", "chisel", "knife", "tinderbox", "needle", "saw", "crystal saw", "spade", "rake",
		"seed dibber", "secateurs", "magic secateurs", "gardening trowel", "small fishing net",
		"big fishing net", "fishing rod", "fly fishing rod", "oily fishing rod", "lobster pot",
		"karambwan vessel", "glassblowing pipe", "pestle and mortar", "machete", "imcando hammer",
		"ammo mould", "amulet mould", "ring mould", "necklace mould", "bracelet mould", "tiara mould",
		"holy mould", "sickle mould", "bolt mould", "unholy mould", "bucket", "empty bucket", "pot",
		"jug", "shears", "noose wand", "butterfly net", "bird snare", "box trap", "rabbit snare",
		"teasing stick", "rope"
	));
	private static final String[] TOOL_SUFFIXES = {
		" pickaxe", " axe", " felling axe", " harpoon", " hammer", " saw", " chisel"
	};
	private static final Set<String> CLEAN_HERBS = new HashSet<>(Arrays.asList(
		"guam leaf", "marrentill", "tarromin", "harralander", "ranarr weed", "toadflax", "irit leaf",
		"avantoe", "kwuarm", "huasca", "snapdragon", "cadantine", "lantadyme", "dwarf weed", "torstol"
	));
	private static final Set<String> GEMS_EXACT = new HashSet<>(Arrays.asList(
		"opal", "jade", "red topaz", "sapphire", "emerald", "ruby", "diamond", "dragonstone", "onyx",
		"zenyte"
	));

	private static final UserRules OVERRIDES = UserRules.parse(Resources.read("overrides.txt"));

	private final UserRules userRules;

	Categoriser(UserRules userRules)
	{
		this.userRules = userRules;
	}

	/**
	 * @param equipment combat stats, or null if the item is not equipable
	 */
	String categorise(int itemId, String name, String[] actions, ItemEquipmentStats equipment)
	{
		String custom = ruleCategory(itemId, name);
		if (custom == null)
		{
			ItemData.Entry data = ItemData.get(name);
			custom = data == null ? null : data.category;
			// For combat gear the item's own stats decide the style; the data only moves gear out of the styles
			// (Slayer, a skill, Cosmetic...).
			if (custom != null && equipment != null && COMBAT_STYLES.contains(custom))
			{
				String byStats = gear(name.toLowerCase(), equipment);
				if (COMBAT_STYLES.contains(byStats))
				{
					custom = byStats;
				}
			}
		}
		return custom != null ? custom : builtIn(name.toLowerCase(), actions, equipment);
	}

	/**
	 * @return the category a user rule or bundled override puts the item in, or null if none matches
	 */
	String ruleCategory(int itemId, String name)
	{
		String custom = userRules.match(itemId, name);
		return custom != null ? custom : OVERRIDES.match(itemId, name);
	}

	static String builtIn(String name, String[] actions, ItemEquipmentStats equipment)
	{
		if (name.equals("coins") || name.equals("platinum token"))
		{
			return CURRENCY;
		}
		// Before equipment: many tools are wieldable and would otherwise land in Melee.
		if (isTool(name))
		{
			return TOOLS;
		}
		// Charged teleport jewellery (glory, games necklace, dueling, wealth, combat bracelet...) is rubbed to
		// teleport; uncharged versions can't be, so they stay with gear. Xeric's talisman works the same way.
		if (hasAction(actions, "Rub") && (equipment != null || name.contains("talisman")))
		{
			return TELEPORTS;
		}
		if (equipment != null)
		{
			return gear(name, equipment);
		}
		// Dwarf multicannon parts and cannonballs.
		if (name.contains("cannon"))
		{
			return RANGED;
		}
		if (hasAction(actions, "Eat"))
		{
			return FOOD;
		}
		if (hasAction(actions, "Drink"))
		{
			return POTIONS;
		}
		if (hasAction(actions, "Bury") || hasAction(actions, "Scatter") || name.startsWith("ensouled "))
		{
			return PRAYER;
		}
		// Blighted spell sacks (ice barrage, entangle, vengeance, teleblock...) are spell supplies.
		if (name.startsWith("blighted ") && name.endsWith(" sack"))
		{
			return RUNES;
		}
		if (hasAction(actions, "Break") || name.contains("teleport") || name.equals("royal seed pod"))
		{
			return TELEPORTS;
		}
		if (name.endsWith(" rune") || name.contains("rune pouch"))
		{
			return RUNES;
		}
		// Crystal armour/weapon/tool seeds are Prifddinas crafting materials, not farming seeds.
		if ((name.contains("seed") && !name.contains("crystal ")) || name.contains("sapling") || name.contains("compost"))
		{
			return FARMING;
		}
		// Unfinished bolts are fletched, not mixed into potions like the other "(unf)" items.
		if (name.endsWith("(unf)") && name.contains(" bolts"))
		{
			return LOGS;
		}
		if (name.startsWith("grimy ") || name.endsWith("(unf)") || CLEAN_HERBS.contains(name)
			|| name.startsWith("vial of ") || name.equals("vial"))
		{
			return HERBLORE;
		}
		if (name.startsWith("uncut ") || GEMS_EXACT.contains(name))
		{
			return GEMS;
		}
		if (name.endsWith(" ore") || name.endsWith(" bar") || name.equals("coal"))
		{
			return ORES_BARS;
		}
		// Pyre logs are burnt for Barbarian Firemaking and shade remains, not fletched.
		if (name.endsWith("pyre logs"))
		{
			return PYRE_LOGS;
		}
		if (name.endsWith("logs"))
		{
			return LOGS;
		}
		if (name.endsWith("plank"))
		{
			return PLANKS;
		}
		if (name.startsWith("clue scroll") || name.startsWith("reward casket") || name.startsWith("clue bottle")
			|| name.startsWith("clue geode") || name.startsWith("clue nest") || name.startsWith("scroll box"))
		{
			return CLUES;
		}
		return MISC;
	}

	static String gear(String name, ItemEquipmentStats e)
	{
		int slot = e.getSlot();
		if (slot == EquipmentInventorySlot.AMMO.getSlotIdx())
		{
			// Arrows, bolts and the rest of the ammo go with Ranged. God blessings use the ammo slot but suit every
			// style; they live with Melee and get copies elsewhere.
			return name.contains("blessing") ? MELEE : RANGED;
		}

		int meleeAttack = Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush()));
		if (slot == EquipmentInventorySlot.WEAPON.getSlotIdx())
		{
			// Staves carry crush bonuses too, so any real magic bonus wins.
			if (e.getAmagic() >= 10 || e.getMdmg() > 0)
			{
				return MAGIC;
			}
			// Darts have ranged strength but no ranged attack bonus.
			if ((e.getArange() > 0 || e.getRstr() > 0) && e.getArange() >= meleeAttack)
			{
				return RANGED;
			}
			if (meleeAttack > 0 || e.getStr() > 0)
			{
				return MELEE;
			}
			return e.getAmagic() > 0 ? MAGIC : OTHER_GEAR;
		}

		// Armour: pick the style with the highest offensive contribution.
		int melee = Math.max(meleeAttack, 0) + e.getStr();
		int ranged = Math.max(e.getArange(), 0) + e.getRstr();
		int magic = Math.max(e.getAmagic(), 0) + Math.round(e.getMdmg());
		if (melee > 0 && melee >= ranged && melee >= magic)
		{
			return MELEE;
		}
		if (ranged > 0 && ranged >= magic)
		{
			return RANGED;
		}
		if (magic > 0)
		{
			return MAGIC;
		}

		// Amulets and rings without combat bonuses: teleport jewellery, ring of suffering, etc.
		if (slot == EquipmentInventorySlot.AMULET.getSlotIdx() || slot == EquipmentInventorySlot.RING.getSlotIdx())
		{
			return JEWELLERY;
		}

		// No offensive stats: plain defensive armour (plate, shields) is tank/melee gear.
		boolean defensive = e.getDstab() > 0 || e.getDslash() > 0 || e.getDcrush() > 0
			|| e.getDmagic() > 0 || e.getDrange() > 0;
		return defensive ? MELEE : OTHER_GEAR;
	}

	static boolean isTool(String name)
	{
		if (TOOLS_EXACT.contains(name) || name.startsWith("watering can"))
		{
			return true;
		}
		for (String suffix : TOOL_SUFFIXES)
		{
			if (name.endsWith(suffix))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean hasAction(String[] actions, String action)
	{
		if (actions != null)
		{
			for (String a : actions)
			{
				if (action.equalsIgnoreCase(a))
				{
					return true;
				}
			}
		}
		return false;
	}
}

