/**
 * A window for arranging the categories: which there are and their order, the tab each shows in, and the items the
 * user has put in each. Every change is saved as it's made, so the bank re-sorts behind the window.
 */
final class CategoryEditor
{
	private static final Color SUBTLE = ColorScheme.LIGHT_GRAY_COLOR;
	private static final Color ERROR = new Color(0xE0605A);
	private static final String NO_TAB = "No tab";
	private static final String NEW_TAB = "New tab...";
	private static final int SEARCH_DELAY_MS = 250;

	private final Supplier<CategorySettings> load;
	private final Consumer<CategorySettings> save;
	private final ItemLookup items;

	private JDialog dialog;
	private CategorySettings settings;
	private String selected;
	// Set while the editor itself changes the list, whose selection events would otherwise select as they go.
	private boolean listUpdating;
	private boolean tabsUpdating;
	// Answers for an earlier category or search than the current one are dropped.
	private int describeToken;
	private int searchToken;
	private List<ItemLookup.Row> results = Collections.emptyList();

	private final DefaultListModel<String> categoryModel = new DefaultListModel<>();
	private JList<String> categoryList;
	private int hoverIndex = -1;
	// The list index of the category being dragged, while the mouse is down on the list.
	private int dragFrom = -1;
	private JLabel title;
	private JLabel kind;
	private JButton rename;
	private JButton delete;
	private JComboBox<String> tabBox;
	private JLabel tabHint;
	private JLabel itemsTitle;
	private JLabel itemsHint;
	private JPanel itemRows;
	private JLabel addTitle;
	private IconTextField search;
	private JPanel resultRows;
	private Timer searchTimer;

	CategoryEditor(Supplier<CategorySettings> load, Consumer<CategorySettings> save, ItemLookup items)
	{
		this.load = load;
		this.save = save;
		this.items = items;
	}

	/**
	 * Opens the window, or brings it to the front.
	 *
	 * @param near a component in the window to open it over
	 */
	void open(Component near)
	{
		prepare(SwingUtilities.getWindowAncestor(near));
		if (!dialog.isVisible())
		{
			dialog.setLocationRelativeTo(dialog.getOwner());
			dialog.setVisible(true);
		}
		dialog.toFront();
	}

	/**
	 * Builds the window if it isn't yet, showing the current settings, without opening it.
	 */
	JDialog prepare(Window owner)
	{
		if (dialog == null)
		{
			build(owner);
		}
		settings = load.get();
		refresh();
		return dialog;
	}

	/**
	 * Picks up settings changed elsewhere: Move to in the bank, or the text settings.
	 */
	void reload()
	{
		if (dialog == null || !dialog.isVisible())
		{
			return;
		}
		CategorySettings fresh = load.get();
		if (!signature(fresh).equals(signature(settings)))
		{
			settings = fresh;
			refresh();
		}
	}

	void close()
	{
		if (dialog != null)
		{
			searchTimer.stop();
			dialog.dispose();
			dialog = null;
		}
	}

	private static String signature(CategorySettings s)
	{
		return s.rulesText() + "\0" + s.alsoShowText() + "\0" + s.orderText() + "\0" + s.tabsText();
	}

	private void edit(Consumer<CategorySettings> change)
	{
		CategorySettings s = load.get();
		change.accept(s);
		save.accept(s);
		settings = s;
		refresh();
	}

	// Building the window

	private void build(Window owner)
	{
		dialog = new JDialog(owner, "Bank categories", Dialog.ModalityType.MODELESS);
		dialog.setDefaultCloseOperation(WindowConstants.HIDE_ON_CLOSE);

		JPanel root = new JPanel(new BorderLayout());
		root.setBackground(ColorScheme.DARK_GRAY_COLOR);
		root.add(buildCategoryColumn(), BorderLayout.WEST);

		JPanel detail = new JPanel(new BorderLayout(0, 10));
		detail.setOpaque(false);
		detail.setBorder(new EmptyBorder(10, 4, 0, 10));
		detail.add(buildHeader(), BorderLayout.NORTH);
		JPanel columns = new JPanel(new GridLayout(1, 2, 10, 0));
		columns.setOpaque(false);
		columns.add(buildItemsColumn());
		columns.add(buildAddColumn());
		detail.add(columns, BorderLayout.CENTER);
		root.add(detail, BorderLayout.CENTER);
		root.add(buildFooter(), BorderLayout.SOUTH);

		dialog.setContentPane(root);
		dialog.setSize(1000, 600);
		dialog.setMinimumSize(new Dimension(780, 440));
	}

	private JComponent buildCategoryColumn()
	{
		JPanel column = new JPanel(new BorderLayout(0, 6));
		column.setOpaque(false);
		column.setBorder(new EmptyBorder(10, 10, 0, 10));
		column.setPreferredSize(new Dimension(240, 0));
		column.add(heading(new JLabel("Categories"), hint("As in your bank. Drag to reorder.")),
			BorderLayout.NORTH);

		categoryList = new JList<>(categoryModel);
		categoryList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		categoryList.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		categoryList.setCellRenderer(new CategoryCell());
		categoryList.addListSelectionListener(e ->
		{
			// While dragging, the list selects whatever is under the mouse; the drop selects the dragged category.
			if (!listUpdating && dragFrom < 0 && !e.getValueIsAdjusting() && categoryList.getSelectedValue() != null)
			{
				select(categoryList.getSelectedValue());
			}
		});
		ReorderMouse reorder = new ReorderMouse();
		categoryList.addMouseListener(reorder);
		categoryList.addMouseMotionListener(reorder);
		column.add(scroll(categoryList), BorderLayout.CENTER);

		JButton add = new JButton("+ New category");
		add.setToolTipText("Make a category of your own, then add items to it");
		add.addActionListener(e -> newCategory());
		column.add(add, BorderLayout.SOUTH);
		return column;
	}

	private JComponent buildHeader()
	{
		JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(new EmptyBorder(8, 10, 8, 10));

		JPanel top = new JPanel(new BorderLayout(10, 0));
		top.setOpaque(false);
		title = new JLabel();
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		kind = hint("");
		JPanel names = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 0));
		names.setOpaque(false);
		names.add(title);
		names.add(kind);
		top.add(names, BorderLayout.CENTER);

		rename = new JButton("Rename");
		rename.addActionListener(e -> renameCategory());
		delete = new JButton("Delete");
		delete.addActionListener(e -> deleteCategory());
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
		buttons.setOpaque(false);
		buttons.add(rename);
		buttons.add(delete);
		// Hidden for built-in categories; the header keeps its height so the columns below don't jump.
		buttons.setPreferredSize(buttons.getPreferredSize());
		top.add(buttons, BorderLayout.EAST);
		header.add(top, BorderLayout.NORTH);

		JPanel tabRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 0));
		tabRow.setOpaque(false);
		JLabel tabLabel = new JLabel("Bank tab");
		tabLabel.setFont(FontManager.getRunescapeFont());
		tabLabel.setForeground(ColorScheme.TEXT_COLOR);
		tabBox = new JComboBox<>();
		tabBox.setPreferredSize(new Dimension(190, tabBox.getPreferredSize().height));
		tabBox.addActionListener(e -> tabChosen());
		tabHint = hint("");
		tabRow.add(tabLabel);
		tabRow.add(tabBox);
		tabRow.add(tabHint);
		header.add(tabRow, BorderLayout.SOUTH);
		return header;
	}

	private JComponent buildItemsColumn()
	{
		JPanel column = new JPanel(new BorderLayout(0, 6));
		column.setOpaque(false);
		itemsTitle = new JLabel();
		itemsHint = hint("");
		column.add(heading(itemsTitle, itemsHint), BorderLayout.NORTH);
		itemRows = rowList();
		column.add(scroll(top(itemRows)), BorderLayout.CENTER);
		return column;
	}

	private JComponent buildAddColumn()
	{
		JPanel column = new JPanel(new BorderLayout(0, 6));
		column.setOpaque(false);

		addTitle = new JLabel();
		search = new IconTextField();
		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(0, 30));
		search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		search.setHoverBackgroundColor(ColorScheme.DARKER_GRAY_HOVER_COLOR);
		searchTimer = new Timer(SEARCH_DELAY_MS, e -> runSearch());
		searchTimer.setRepeats(false);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				searchTimer.restart();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				searchTimer.restart();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				searchTimer.restart();
			}
		});
		search.addClearListener(this::runSearch);

		JPanel top = new JPanel(new BorderLayout(0, 6));
		top.setOpaque(false);
		top.add(heading(addTitle, hint("Search your bank, or any item in the game.")), BorderLayout.NORTH);
		top.add(search, BorderLayout.CENTER);
		top.add(hint("Tip: * matches anything, e.g. *slayer ring*"), BorderLayout.SOUTH);
		column.add(top, BorderLayout.NORTH);

		resultRows = rowList();
		column.add(scroll(top(resultRows)), BorderLayout.CENTER);
		return column;
	}

	private JComponent buildFooter()
	{
		JPanel footer = new JPanel(new BorderLayout());
		footer.setOpaque(false);
		footer.setBorder(new EmptyBorder(8, 10, 10, 10));
		footer.add(hint("Changes show in your bank straight away. In the bank, right-click an item and pick Move to"
			+ " for a quick move."), BorderLayout.CENTER);
		JButton done = new JButton("Done");
		done.addActionListener(e -> dialog.setVisible(false));
		footer.add(done, BorderLayout.EAST);
		return footer;
	}

	// Showing the settings

	private void refresh()
	{
		List<String> categories = settings.categories();
		if (selected == null || !categories.contains(selected))
		{
			selected = categories.get(0);
		}
		listUpdating = true;
		categoryModel.clear();
		categories.forEach(categoryModel::addElement);
		categoryList.setSelectedValue(selected, true);
		listUpdating = false;
		showSelected();
		runSearch();
	}

	private void select(String category)
	{
		if (!category.equals(selected))
		{
			selected = category;
			showSelected();
			showResults();
		}
	}

	private void showSelected()
	{
		boolean custom = !CategorySettings.isBuiltIn(selected);
		title.setText(selected);
		kind.setText(custom ? "Your category" : "Built-in category");
		rename.setVisible(custom);
		delete.setVisible(custom);

		tabsUpdating = true;
		tabBox.removeAllItems();
		tabBox.addItem(NO_TAB);
		settings.tabs().forEach(tabBox::addItem);
		tabBox.addItem(NEW_TAB);
		String tab = settings.tabOf(selected);
		tabBox.setSelectedItem(tab != null ? tab : NO_TAB);
		tabsUpdating = false;
		tabHint.setText(tab != null ? "Its tab down the left of the bank shows it." : "It only shows in the full bank.");

		// Moved items first, then the ones added here, which stay where they are too.
		List<String> patterns = new ArrayList<>(settings.items(selected));
		int moved = patterns.size();
		patterns.addAll(settings.alsoShown(selected));
		itemsTitle.setText((custom ? "In " : "Added to ") + selected + (patterns.isEmpty() ? "" : " (" + patterns.size() + ")"));
		itemsHint.setText(custom ? "Items you moved or added here."
			: "Items you moved or added here. Others are sorted in automatically.");
		addTitle.setText("Add to " + selected);

		int token = ++describeToken;
		if (patterns.isEmpty())
		{
			showItems(Collections.emptyList(), 0);
			return;
		}
		items.describe(patterns, rows ->
		{
			if (token == describeToken)
			{
				showItems(rows, moved);
			}
		});
	}

	/**
	 * @param moved how many of the rows, from the first, are moved here; the rest are added here
	 */
	private void showItems(List<ItemLookup.Row> rows, int moved)
	{
		itemRows.removeAll();
		if (rows.isEmpty())
		{
			itemRows.add(emptyState(CategorySettings.isBuiltIn(selected)
				? "You haven't moved or added anything here. Search on the right to find items."
				: "Nothing here yet. Search on the right to add items."));
		}
		for (int i = 0; i < rows.size(); i++)
		{
			ItemLookup.Row row = rows.get(i);
			boolean wasMoved = i < moved;
			// An added item the bank doesn't have shows as a placeholder.
			boolean notOwned = !wasMoved && !row.inBank && row.itemId >= 0 && !ItemLookup.isGroup(row);
			ItemLookup.Row labelled = new ItemLookup.Row(row.itemId, row.name, row.pattern,
				(wasMoved ? "Moved here" : notOwned ? "Added here · shown as a placeholder" : "Added here · " + stillIn(row))
					+ (row.detail.isEmpty() ? "" : " · " + row.detail),
				row.category, row.inBank);
			JButton remove = new JButton("Remove");
			remove.setToolTipText(wasMoved ? "Send it back to its usual category"
				: notOwned ? "Stop showing it in " + selected
				: "Take it out of " + selected + ". It stays in " + stillIn(row).substring("still in ".length()) + ".");
			remove.addActionListener(e -> edit(s -> s.removeItem(selected, row.pattern)));
			itemRows.add(itemRow(labelled, remove));
		}
		itemRows.revalidate();
		itemRows.repaint();
	}

	private void runSearch()
	{
		searchTimer.stop();
		String text = search.getText().trim();
		int token = ++searchToken;
		if (text.isEmpty())
		{
			results = Collections.emptyList();
			search.setIcon(IconTextField.Icon.SEARCH);
			showResults();
			return;
		}
		search.setIcon(IconTextField.Icon.LOADING_DARKER);
		items.search(text, rows ->
		{
			if (token == searchToken)
			{
				results = rows;
				search.setIcon(IconTextField.Icon.SEARCH);
				showResults();
			}
		});
	}

	private void showResults()
	{
		resultRows.removeAll();
		if (results.isEmpty())
		{
			resultRows.add(emptyState(search.getText().trim().isEmpty()
				? "Type part of an item's name." : "No items match."));
		}
		List<String> movedHere = settings.items(selected);
		List<String> shownHere = settings.alsoShown(selected);
		for (ItemLookup.Row row : results)
		{
			boolean group = ItemLookup.isGroup(row);
			JButton move = new JButton("Move");
			JButton add = new JButton("Add");
			// Told apart from Move at a glance.
			add.setForeground(ColorScheme.BRAND_ORANGE);
			if (movedHere.stream().anyMatch(row.pattern::equalsIgnoreCase))
			{
				move.setText("Moved");
				move.setEnabled(false);
			}
			else if (selected.equals(row.category) && (row.inBank || ItemLookup.isGroup(row)))
			{
				// It's here without a rule: nothing to move or show.
				move.setText("Here");
				move.setEnabled(false);
				add.setEnabled(false);
				move.setToolTipText("Already sorted into " + selected);
				add.setToolTipText("Already sorted into " + selected);
			}
			else if (selected.equals(row.category))
			{
				// Its category, but not in the bank: it can still be added to show it as a placeholder.
				move.setText("Here");
				move.setEnabled(false);
				move.setToolTipText("Already sorted into " + selected);
			}
			if (shownHere.stream().anyMatch(row.pattern::equalsIgnoreCase))
			{
				add.setText("Added");
				add.setEnabled(false);
			}
			String from = row.category != null ? row.category : "their categories";
			if (move.isEnabled())
			{
				move.setToolTipText((group ? "Take them out of their categories" : "Take it out of " + from)
					+ " and put " + (group ? "them" : "it") + " in " + selected);
				move.addActionListener(e -> edit(s -> s.addItem(selected, row.pattern)));
			}
			if (add.isEnabled())
			{
				add.setToolTipText(!group && !row.inBank ? "Show it as a placeholder in " + selected + " while it isn't in your bank"
					: (group ? "Keep them where they are" : "Keep it in " + from)
					+ " and add " + (group ? "them" : "it") + " to " + selected + " too");
				add.addActionListener(e -> edit(s -> s.addAlsoShown(selected, row.pattern)));
			}
			resultRows.add(itemRow(row, move, add));
		}
		resultRows.revalidate();
		resultRows.repaint();
	}

	// Actions

	private void newCategory()
	{
		String name = askName("New category", "Name your new category:", "", settings.categories());
		if (name != null)
		{
			selected = name;
			edit(s -> s.create(name));
			search.requestFocusInWindow();
		}
	}

	private void renameCategory()
	{
		List<String> taken = settings.categories();
		taken.remove(selected);
		String name = askName("Rename category", "New name for " + selected + ":", selected, taken);
		if (name != null && !name.equals(selected))
		{
			String from = selected;
			selected = name;
			edit(s -> s.rename(from, name));
		}
	}

	private void deleteCategory()
	{
		int count = settings.items(selected).size();
		String message = "Delete " + selected + "?" + (count == 0 ? ""
			: count == 1 ? "\nThe item in it goes back to its usual category."
			: "\nThe " + count + " items in it go back to their usual categories.");
		if (JOptionPane.showConfirmDialog(dialog, message, "Delete category", JOptionPane.OK_CANCEL_OPTION,
			JOptionPane.PLAIN_MESSAGE) != JOptionPane.OK_OPTION)
		{
			return;
		}
		String gone = selected;
		int index = categoryModel.indexOf(gone);
		selected = categoryModel.get(index > 0 ? index - 1 : Math.min(1, categoryModel.size() - 1));
		edit(s -> s.delete(gone));
	}

	private void tabChosen()
	{
		Object choice = tabBox.getSelectedItem();
		if (tabsUpdating || choice == null)
		{
			return;
		}
		String category = selected;
		if (NEW_TAB.equals(choice))
		{
			String tab = askName("New tab", "Name the new tab:", "", settings.tabs());
			if (tab == null)
			{
				showSelected();
				return;
			}
			edit(s -> s.setTab(category, tab));
		}
		else if (!choice.equals(settings.tabOf(category) == null ? NO_TAB : settings.tabOf(category)))
		{
			edit(s -> s.setTab(category, NO_TAB.equals(choice) ? null : (String) choice));
		}
	}

	private String askName(String heading, String message, String initial, List<String> taken)
	{
		String name = initial;
		while (true)
		{
			name = (String) JOptionPane.showInputDialog(dialog, message, heading, JOptionPane.PLAIN_MESSAGE, null, null,
				name);
			if (name == null)
			{
				return null;
			}
			name = name.trim();
			String problem = CategorySettings.nameProblem(name, taken);
			if (problem == null)
			{
				return name;
			}
			JOptionPane.showMessageDialog(dialog, problem, heading, JOptionPane.WARNING_MESSAGE);
		}
	}

	// Where an item added to a category also stays.
	private static String stillIn(ItemLookup.Row row)
	{
		return "still in " + (row.category != null ? row.category : ItemLookup.isGroup(row) ? "their categories"
			: "its category");
	}

	// Pieces

	private static JLabel hint(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(SUBTLE);
		return label;
	}

	private static JComponent heading(JLabel title, JLabel hint)
	{
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		JPanel panel = new JPanel(new GridLayout(2, 1));
		panel.setOpaque(false);
		panel.add(title);
		panel.add(hint);
		return panel;
	}

	private static JPanel rowList()
	{
		JPanel rows = new JPanel(new DynamicGridLayout(0, 1, 0, 3));
		rows.setOpaque(false);
		return rows;
	}

	private static JComponent top(JComponent rows)
	{
		ScrollableRows wrapper = new ScrollableRows();
		wrapper.add(rows, BorderLayout.NORTH);
		return wrapper;
	}

	/**
	 * Rows at the top of their scroll pane and as wide as it, so that long names are cut short rather than push the
	 * buttons out of sight.
	 */
	private static final class ScrollableRows extends JPanel implements Scrollable
	{
		ScrollableRows()
		{
			super(new BorderLayout());
			setOpaque(false);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	private static JScrollPane scroll(JComponent view)
	{
		JScrollPane scroll = new JScrollPane(view, ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getViewport().setOpaque(false);
		scroll.setOpaque(false);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		return scroll;
	}

	private static JComponent emptyState(String text)
	{
		JLabel label = new JLabel("<html>" + text + "</html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(SUBTLE);
		label.setBorder(new EmptyBorder(8, 4, 8, 4));
		return label;
	}

	private JComponent itemRow(ItemLookup.Row row, JButton... buttons)
	{
		JPanel panel = new JPanel(new BorderLayout(8, 0));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(new EmptyBorder(2, 4, 2, 6));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		if (row.itemId >= 0)
		{
			items.icon(row.itemId, icon);
		}
		panel.add(icon, BorderLayout.WEST);

		JLabel name = new JLabel(row.name);
		name.setFont(FontManager.getRunescapeFont());
		name.setForeground(Color.WHITE);
		JLabel detail = hint(row.detail);
		// An item name or ID that nothing has, likely a typo; a pattern may be for items not in the game yet.
		if (row.itemId < 0 && !ItemLookup.isGroup(row))
		{
			detail.setForeground(ERROR);
		}
		JPanel text = new JPanel(new GridLayout(2, 1));
		text.setOpaque(false);
		text.add(name);
		text.add(detail);
		panel.add(text, BorderLayout.CENTER);

		JPanel right = new JPanel(new GridBagLayout());
		right.setOpaque(false);
		JPanel buttonRow = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		buttonRow.setOpaque(false);
		for (JButton button : buttons)
		{
			button.setFont(FontManager.getRunescapeSmallFont());
			button.setMargin(new Insets(2, 6, 2, 6));
			buttonRow.add(button);
		}
		right.add(buttonRow);
		panel.add(right, BorderLayout.EAST);

		MouseAdapter hover = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				panel.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		};
		panel.addMouseListener(hover);
		return panel;
	}

	/**
	 * A category in the list: a grip to drag it by, its name and the tab it shows in. The user's own categories
	 * have an orange edge.
	 */
	private final class CategoryCell extends JPanel implements ListCellRenderer<String>
	{
		private final JLabel name = new JLabel();
		private final JLabel tab = hint("");
		private boolean custom;

		CategoryCell()
		{
			super(new BorderLayout(6, 0));
			setBorder(new EmptyBorder(5, 18, 5, 8));
			name.setFont(FontManager.getRunescapeFont());
			add(name, BorderLayout.CENTER);
			add(tab, BorderLayout.EAST);
		}

		@Override
		public Component getListCellRendererComponent(JList<? extends String> list, String value, int index,
			boolean isSelected, boolean cellHasFocus)
		{
			name.setText(value);
			name.setForeground(isSelected ? Color.WHITE : ColorScheme.TEXT_COLOR);
			String tabName = settings.tabOf(value);
			tab.setText(tabName != null ? tabName : "");
			custom = !CategorySettings.isBuiltIn(value);
			setBackground(isSelected ? ColorScheme.MEDIUM_GRAY_COLOR
				: index == hoverIndex ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			return this;
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			g.setColor(ColorScheme.MEDIUM_GRAY_COLOR.brighter());
			int top = getHeight() / 2 - 4;
			for (int row = 0; row < 3; row++)
			{
				for (int col = 0; col < 2; col++)
				{
					g.fillRect(7 + col * 3, top + row * 3, 2, 2);
				}
			}
			if (custom)
			{
				g.setColor(ColorScheme.BRAND_ORANGE);
				g.fillRect(0, 0, 3, getHeight());
			}
		}
	}

	/**
	 * Dragging a category moves it through the list as the mouse goes; the order is saved when it's dropped.
	 */
	private final class ReorderMouse extends MouseAdapter
	{
		private boolean moved;

		@Override
		public void mousePressed(MouseEvent e)
		{
			dragFrom = categoryList.locationToIndex(e.getPoint());
			moved = false;
		}

		@Override
		public void mouseDragged(MouseEvent e)
		{
			int to = categoryList.locationToIndex(e.getPoint());
			if (dragFrom < 0 || to < 0 || to == dragFrom)
			{
				return;
			}
			listUpdating = true;
			String category = categoryModel.remove(dragFrom);
			categoryModel.add(to, category);
			categoryList.setSelectedIndex(to);
			listUpdating = false;
			categoryList.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));
			hoverIndex = to;
			dragFrom = to;
			moved = true;
		}

		@Override
		public void mouseReleased(MouseEvent e)
		{
			categoryList.setCursor(Cursor.getDefaultCursor());
			int index = dragFrom;
			dragFrom = -1;
			if (index < 0)
			{
				return;
			}
			String category = categoryModel.get(index);
			if (moved)
			{
				selected = category;
				edit(s -> s.move(category, index));
			}
			else
			{
				select(category);
			}
		}

		@Override
		public void mouseMoved(MouseEvent e)
		{
			setHover(categoryList.locationToIndex(e.getPoint()));
		}

		@Override
		public void mouseExited(MouseEvent e)
		{
			setHover(-1);
		}

		private void setHover(int index)
		{
			if (index != hoverIndex)
			{
				hoverIndex = index;
				categoryList.repaint();
			}
		}
	}
}

package com.smartbanksorter;

import java.util.List;

/**
 * Bank searches that name categories: a whole category name, e.g. "crafting", adds that category's items to the
 * game's own name matches, and a few letters of one suggest jumping to it.
 */
final class CategorySearch
{
	// Fewer letters than this match too many categories to be worth suggesting.
	static final int MIN_SUGGEST_LENGTH = 3;

	private CategorySearch()
	{
	}

	/**
	 * @return the category a search names in full, or null if it doesn't name one
	 */
	static String parse(String search, List<String> order)
	{
		String text = search.trim();
		for (String category : order)
		{
			if (category.equalsIgnoreCase(text))
			{
				return category;
			}
		}
		return null;
	}

	/**
	 * @return the first category whose name, or failing that one of its words, starts with the search; null if
	 * none does or the search is too short
	 */
	static String suggest(String search, List<String> order)
	{
		String text = search == null ? "" : search.trim().toLowerCase();
		if (text.length() < MIN_SUGGEST_LENGTH)
		{
			return null;
		}
		for (String category : order)
		{
			if (category.toLowerCase().startsWith(text))
			{
				return category;
			}
		}
		for (String category : order)
		{
			for (String word : category.toLowerCase().split("[^a-z0-9]+"))
			{
				if (word.startsWith(text))
				{
					return category;
				}
			}
		}
		return null;
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * The custom rules (items moved and items also shown), category order, tabs and collapsed categories, edited together
 * by the category editor. The
 * settings stay plain text: each edit rewrites only the lines it touches, so hand-written lines and comments stay as
 * they were.
 */
final class CategorySettings
{
	private final String savedRules;
	private final String savedAlsoShow;
	private final String savedOrder;
	private final String savedTabs;
	private final String savedCollapsed;
	private final Lines rules;
	private final Lines alsoShow;
	private final Lines tabs;
	private final List<String> collapsed;
	private List<String> order;
	private boolean orderChanged;

	CategorySettings(String rules, String alsoShow, String order, String tabs, String collapsed)
	{
		savedRules = rules;
		savedAlsoShow = alsoShow;
		savedOrder = order;
		savedTabs = tabs;
		savedCollapsed = collapsed;
		this.rules = new Lines(rules);
		this.alsoShow = new Lines(alsoShow);
		this.tabs = new Lines(tabs);
		this.collapsed = new ArrayList<>(Text.fromCSV(collapsed));
		this.order = order(order, UserRules.parse(rules), UserRules.parse(alsoShow));
	}

	static CategorySettings load(SmartBankSorterConfig config)
	{
		return new CategorySettings(config.customRules(), config.alsoShow(), config.categoryOrder(), config.tabGroups(),
			config.collapsed());
	}

	/**
	 * Every category top to bottom: the ones the order lists, then the built-ins it doesn't, then new ones rules name.
	 */
	static List<String> order(String orderText, UserRules rules, UserRules alsoShow)
	{
		Set<String> order = new LinkedHashSet<>();
		for (String s : orderText.split("[\\n,]"))
		{
			if (!s.trim().isEmpty())
			{
				order.add(s.trim());
			}
		}
		order.addAll(Categories.DEFAULT_ORDER);
		order.addAll(rules.categories());
		order.addAll(alsoShow.categories());
		return new ArrayList<>(order);
	}

	/**
	 * Why a category or tab can't have this name, or null if it can.
	 */
	static String nameProblem(String name, Collection<String> taken)
	{
		if (name.isEmpty())
		{
			return "Enter a name.";
		}
		if (name.matches(".*[:,*\\n].*") || name.startsWith("#"))
		{
			return "Names can't contain : , or *";
		}
		if (name.length() > 30)
		{
			return "Keep it to 30 letters or fewer.";
		}
		if (name.equalsIgnoreCase(RecentDeposits.CATEGORY))
		{
			return "'" + RecentDeposits.CATEGORY + "' is the plugin's own.";
		}
		for (String other : taken)
		{
			if (other.equalsIgnoreCase(name))
			{
				return "'" + other + "' already exists.";
			}
		}
		return null;
	}

	List<String> categories()
	{
		return new ArrayList<>(order);
	}

	static boolean isBuiltIn(String category)
	{
		return Categories.DEFAULT_ORDER.contains(category);
	}

	/**
	 * The patterns the user's rules move into this category, in the order they're tried.
	 */
	List<String> items(String category)
	{
		return rules.values(category);
	}

	/**
	 * The patterns whose items this category also shows, while they stay where they are.
	 */
	List<String> alsoShown(String category)
	{
		return alsoShow.values(category);
	}

	List<String> tabs()
	{
		return tabs.keys();
	}

	/**
	 * The tab this category shows in, or null.
	 */
	String tabOf(String category)
	{
		return tabs.keyOf(category);
	}

	/**
	 * Puts an item, or the items a pattern matches, in a category. It takes over any rule the user had for the same
	 * pattern, and goes first so that it wins over broader lines.
	 */
	void addItem(String category, String pattern)
	{
		rules.removeValue(null, pattern);
		alsoShow.removeValue(category, pattern);
		rules.add(0, category, pattern);
	}

	/**
	 * Shows an item, or the items a pattern matches, in a category as well as where it is. An item can be shown in
	 * any number of categories this way.
	 */
	void addAlsoShown(String category, String pattern)
	{
		rules.removeValue(category, pattern);
		alsoShow.removeValue(category, pattern);
		alsoShow.append(category, pattern);
	}

	// Whether it was moved here or also shown here.
	void removeItem(String category, String pattern)
	{
		rules.removeValue(category, pattern);
		alsoShow.removeValue(category, pattern);
	}

	/**
	 * A new, empty category at the bottom. Only the order knows it until something is put in it.
	 */
	void create(String name)
	{
		order.add(name);
		orderChanged = true;
	}

	void rename(String from, String to)
	{
		rules.renameKey(from, to);
		alsoShow.renameKey(from, to);
		tabs.renameValue(from, to);
		order.set(order.indexOf(from), to);
		orderChanged = true;
		collapsed.replaceAll(c -> c.equals(from) ? to : c);
	}

	/**
	 * Removes a custom category: its items go back to where they'd be without it.
	 */
	void delete(String name)
	{
		rules.removeKey(name);
		alsoShow.removeKey(name);
		tabs.removeValue(null, name);
		order.remove(name);
		orderChanged = true;
		collapsed.remove(name);
	}

	void move(String category, int index)
	{
		order.remove(category);
		order.add(index, category);
		orderChanged = true;
	}

	/**
	 * @param tab the tab to show the category in, a new one if no tab has this name yet; null for none
	 */
	void setTab(String category, String tab)
	{
		tabs.removeValue(null, category);
		if (tab != null)
		{
			tabs.append(tab, category);
		}
	}

	String rulesText()
	{
		return rules.text();
	}

	String alsoShowText()
	{
		return alsoShow.text();
	}

	String tabsText()
	{
		return tabs.text();
	}

	String orderText()
	{
		return orderChanged ? String.join("\n", order) : savedOrder;
	}

	String collapsedText()
	{
		return collapsed.equals(Text.fromCSV(savedCollapsed)) ? savedCollapsed : Text.toCSV(collapsed);
	}

	/**
	 * Writes the settings that changed; the plugin re-sorts the bank as each one does.
	 */
	void save(ConfigManager configManager)
	{
		save(configManager, SmartBankSorterConfig.RULES_KEY, savedRules, rulesText());
		save(configManager, SmartBankSorterConfig.ALSO_SHOW_KEY, savedAlsoShow, alsoShowText());
		save(configManager, SmartBankSorterConfig.ORDER_KEY, savedOrder, orderText());
		save(configManager, SmartBankSorterConfig.TABS_KEY, savedTabs, tabsText());
		save(configManager, SmartBankSorterConfig.COLLAPSED_KEY, savedCollapsed, collapsedText());
	}

	private static void save(ConfigManager configManager, String key, String saved, String text)
	{
		if (!saved.equals(text))
		{
			configManager.setConfiguration(SmartBankSorterConfig.GROUP, key, text);
		}
	}

	/**
	 * "Key: value, value" lines, the syntax of both the rules and the tabs. Lines that aren't, comments and blank
	 * lines, are kept as they are.
	 */
	private static final class Lines
	{
		private static final class Line
		{
			final String raw;
			String key;
			final List<String> values = new ArrayList<>();
			boolean edited;

			Line(String raw)
			{
				this.raw = raw;
				String trimmed = raw.trim();
				int colon = trimmed.indexOf(':');
				if (!trimmed.startsWith("#") && colon > 0)
				{
					key = trimmed.substring(0, colon).trim();
					for (String value : trimmed.substring(colon + 1).split(","))
					{
						if (!value.trim().isEmpty())
						{
							values.add(value.trim());
						}
					}
				}
			}

			Line(String key, String value)
			{
				raw = null;
				this.key = key;
				values.add(value);
				edited = true;
			}

			String text()
			{
				return edited ? key + ": " + String.join(", ", values) : raw;
			}
		}

		private final List<Line> lines = new ArrayList<>();

		Lines(String text)
		{
			if (!text.isEmpty())
			{
				for (String raw : text.split("\\R", -1))
				{
					lines.add(new Line(raw));
				}
			}
		}

		List<String> values(String key)
		{
			List<String> values = new ArrayList<>();
			for (Line line : lines)
			{
				if (key.equals(line.key))
				{
					values.addAll(line.values);
				}
			}
			return values;
		}

		List<String> keys()
		{
			Set<String> keys = new LinkedHashSet<>();
			for (Line line : lines)
			{
				if (line.key != null)
				{
					keys.add(line.key);
				}
			}
			return new ArrayList<>(keys);
		}

		String keyOf(String value)
		{
			for (Line line : lines)
			{
				if (line.key != null && line.values.stream().anyMatch(value::equalsIgnoreCase))
				{
					return line.key;
				}
			}
			return null;
		}

		void add(int index, String key, String value)
		{
			lines.add(index, new Line(key, value));
		}

		// Onto the key's first line, or a new line at the end.
		void append(String key, String value)
		{
			for (Line line : lines)
			{
				if (key.equals(line.key))
				{
					line.values.add(value);
					line.edited = true;
					return;
				}
			}
			lines.add(new Line(key, value));
		}

		// From the key's lines, or every line when key is null. A line left with no values goes.
		void removeValue(String key, String value)
		{
			lines.removeIf(line ->
			{
				if (line.key == null || key != null && !key.equals(line.key)
					|| !line.values.removeIf(value::equalsIgnoreCase))
				{
					return false;
				}
				line.edited = true;
				return line.values.isEmpty();
			});
		}

		void removeKey(String key)
		{
			lines.removeIf(line -> key.equals(line.key));
		}

		void renameKey(String from, String to)
		{
			for (Line line : lines)
			{
				if (from.equals(line.key))
				{
					line.key = to;
					line.edited = true;
				}
			}
		}

		void renameValue(String from, String to)
		{
			for (Line line : lines)
			{
				if (line.key != null && line.values.stream().anyMatch(from::equalsIgnoreCase))
				{
					line.values.replaceAll(v -> v.equalsIgnoreCase(from) ? to : v);
					line.edited = true;
				}
			}
		}

		String text()
		{
			List<String> out = new ArrayList<>();
			lines.forEach(line -> out.add(line.text()));
			return String.join("\n", out);
		}
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.function.Function;
import java.util.function.ToIntFunction;

/**
 * Layouts for Food (best heal first, combo food on its own rows) and Potions (one column per potion,
 * doses going down, combat potions first).
 */
final class ConsumableOrder
{
	// Foods that can be eaten on the same tick as normal food.
	private static final List<String> COMBO_FOOD = Arrays.asList(
		"karambwan", "halibut", "batta", "crunchies", "chocolate bomb", "toad's legs", "worm hole", "veg ball", "tangled toad"
	);
	// Potion families in display order; matched by "name contains", most specific first. Raid essentials lead
	// (divine super combat, divine ranging, brews, restores), then other combat boosts, prayer, cures, utility.
	private static final List<String> POTION_ORDER = Arrays.asList(
		"divine super combat", "divine ranging", "saradomin brew", "super restore",
		"super combat", "ranging", "divine bastion", "bastion", "divine magic", "magic potion",
		"divine battlemage", "battlemage", "divine super attack", "super attack", "divine super strength",
		"super strength", "divine super defence", "super defence",
		"prayer potion", "prayer regeneration", "sanfew", "zamorak brew",
		"anti-venom+", "anti-venom", "antidote++", "antidote+", "superantipoison", "antipoison",
		"extended super antifire", "super antifire", "extended antifire", "antifire",
		"stamina", "super energy", "energy potion", "attack potion", "strength potion", "defence potion"
	);

	private ConsumableOrder()
	{
	}

	static <T> List<List<T>> food(List<T> items, Function<T, String> name, ToIntFunction<T> heal,
		Comparator<T> tiebreak)
	{
		List<T> normal = new ArrayList<>();
		List<T> combo = new ArrayList<>();
		for (T item : items)
		{
			(isCombo(name.apply(item)) ? combo : normal).add(item);
		}
		Comparator<T> order = Comparator.comparingInt(heal).reversed().thenComparing(tiebreak);
		normal.sort(order);
		combo.sort(order);

		List<List<T>> rows = new ArrayList<>();
		if (!normal.isEmpty())
		{
			rows.add(normal);
		}
		if (!combo.isEmpty())
		{
			rows.add(combo);
		}
		return rows;
	}

	static boolean isCombo(String name)
	{
		String n = name.toLowerCase();
		return COMBO_FOOD.stream().anyMatch(n::contains);
	}

	/**
	 * @param compact stack each column's potions straight down, each potion's doses highest first, with no gaps
	 * @return rows of cells; each block of up to {@code columns} potions has one row per dose, highest first,
	 * with null where a potion lacks that dose (unless compact). Undosed drinks follow.
	 */
	static <T> List<List<T>> potions(List<T> items, Function<T, String> name, Comparator<T> tiebreak, int columns,
		boolean compact)
	{
		Map<String, Map<Integer, T>> families = new LinkedHashMap<>();
		List<T> loose = new ArrayList<>();
		List<String> order = families(items, name, tiebreak, families, loose);

		List<List<T>> rows = new ArrayList<>();
		if (compact)
		{
			// Each column keeps the potions it has in the block layout, stacked straight down with no gaps between
			// blocks.
			List<List<T>> stacks = new ArrayList<>();
			for (int i = 0; i < order.size(); i++)
			{
				if (i < columns)
				{
					stacks.add(new ArrayList<>());
				}
				Map<Integer, T> byDose = new TreeMap<>(Comparator.reverseOrder());
				byDose.putAll(families.get(order.get(i)));
				stacks.get(i % columns).addAll(byDose.values());
			}
			int height = stacks.stream().mapToInt(List::size).max().orElse(0);
			for (int r = 0; r < height; r++)
			{
				List<T> row = new ArrayList<>();
				for (List<T> stack : stacks)
				{
					row.add(r < stack.size() ? stack.get(r) : null);
				}
				while (!row.isEmpty() && row.get(row.size() - 1) == null)
				{
					row.remove(row.size() - 1);
				}
				rows.add(row);
			}
		}
		for (int first = 0; !compact && first < order.size(); first += columns)
		{
			List<String> block = order.subList(first, Math.min(first + columns, order.size()));
			TreeSet<Integer> doses = new TreeSet<>(Comparator.reverseOrder());
			block.forEach(f -> doses.addAll(families.get(f).keySet()));
			for (int dose : doses)
			{
				List<T> row = new ArrayList<>();
				for (String family : block)
				{
					row.add(families.get(family).get(dose));
				}
				while (!row.isEmpty() && row.get(row.size() - 1) == null)
				{
					row.remove(row.size() - 1);
				}
				rows.add(row);
			}
		}
		if (!loose.isEmpty())
		{
			rows.add(loose);
		}
		return rows;
	}

	/**
	 * Sorts the items into potions by name, each a map of dose to item, and drinks without doses.
	 *
	 * @return the potions in layout order
	 */
	private static <T> List<String> families(List<T> items, Function<T, String> name, Comparator<T> tiebreak,
		Map<String, Map<Integer, T>> families, List<T> loose)
	{
		List<T> sorted = new ArrayList<>(items);
		sorted.sort(tiebreak);
		for (T item : sorted)
		{
			String itemName = name.apply(item);
			int dose = Doses.dose(itemName);
			if (dose < 0)
			{
				loose.add(item);
				continue;
			}
			Map<Integer, T> doses = families.computeIfAbsent(Doses.baseName(itemName).toLowerCase(), k -> new LinkedHashMap<>());
			// A second item with the same name and dose (rare) can't share the cell.
			if (doses.putIfAbsent(dose, item) != null)
			{
				loose.add(item);
			}
		}

		List<String> order = new ArrayList<>(families.keySet());
		order.sort(Comparator.comparingInt(ConsumableOrder::potionRank).thenComparing(Comparator.naturalOrder()));
		return order;
	}

	static int potionRank(String family)
	{
		for (int i = 0; i < POTION_ORDER.size(); i++)
		{
			if (family.contains(POTION_ORDER.get(i)))
			{
				return i;
			}
		}
		return POTION_ORDER.size();
	}
}

package com.smartbanksorter;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The bracketed number ending an item's name: a potion's doses, or a piece of jewellery's charges.
 */
final class Doses
{
	private static final Pattern DOSE = Pattern.compile("^(.*?)\\s*\\((\\d+)\\)$");

	private Doses()
	{
	}

	// "Prayer potion(4)" -> "Prayer potion", so doses of one potion stay together.
	static String baseName(String name)
	{
		Matcher m = DOSE.matcher(name);
		return m.matches() ? m.group(1) : name;
	}

	/**
	 * @return the number of doses or charges, or -1 if the name doesn't end in one
	 */
	static int dose(String name)
	{
		Matcher m = DOSE.matcher(name);
		return m.matches() ? Integer.parseInt(m.group(2)) : -1;
	}
}

package com.smartbanksorter;

import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Expected damage per game tick of a loadout against a typical boss, from the OSRS Wiki's formulas (the Maximum
 * melee/ranged/magic hit and Damage per second pages) and the normal-attack effects of the weapons that decide the
 * top of each style. It ranks gear; it isn't a full DPS calculator: no potions, special attacks or monster-specific
 * bonuses, and the best prayer for the style is assumed.
 */
final class DpsCalc
{
	/** The player's real combat levels. */
	static final class Levels
	{
		static final Levels MAXED = new Levels(99, 99, 99, 99);

		final int attack;
		final int strength;
		final int ranged;
		final int magic;

		Levels(int attack, int strength, int ranged, int magic)
		{
			this.attack = attack;
			this.strength = strength;
			this.ranged = ranged;
			this.magic = magic;
		}
	}

	/** An equipped item: its lower-case name and stats. */
	static final class Piece
	{
		final String name;
		final ItemEquipmentStats stats;

		Piece(String name, ItemEquipmentStats stats)
		{
			this.name = name.toLowerCase();
			this.stats = stats;
		}
	}

	// A typical boss: 200 Defence and Magic, +100 in every defence bonus, 3x3 or larger.
	static final int TARGET_DEFENCE = 200;
	static final int TARGET_MAGIC = 200;
	static final int TARGET_DEFENCE_BONUS = 100;
	static final int TARGET_SIZE = 3;
	private static final long DEFENCE_ROLL = (long) (TARGET_DEFENCE + 9) * (TARGET_DEFENCE_BONUS + 64);
	private static final long MAGIC_DEFENCE_ROLL = (long) (TARGET_MAGIC + 9) * (TARGET_DEFENCE_BONUS + 64);

	// Ranged strength of the ammo each launcher is assumed to fire: dragon arrows, bolts, darts, javelins.
	private static final int ARROWS = 60;
	private static final int BOLTS = 122;
	private static final int DARTS = 35;
	private static final int JAVELINS = 150;

	private static final int WEAPON = EquipmentInventorySlot.WEAPON.getSlotIdx();
	private static final int HEAD = EquipmentInventorySlot.HEAD.getSlotIdx();
	private static final int BODY = EquipmentInventorySlot.BODY.getSlotIdx();
	private static final int LEGS = EquipmentInventorySlot.LEGS.getSlotIdx();
	private static final int GLOVES = EquipmentInventorySlot.GLOVES.getSlotIdx();
	private static final int AMMO = EquipmentInventorySlot.AMMO.getSlotIdx();

	private DpsCalc()
	{
	}

	/**
	 * @param gear equipped pieces by equipment slot index, the weapon included
	 * @return expected damage per tick, 0 without a weapon
	 */
	static double perTick(String style, Map<Integer, Piece> gear, Levels levels)
	{
		Piece weapon = gear.get(WEAPON);
		if (weapon == null || weapon.stats == null)
		{
			return 0;
		}
		switch (style)
		{
			case Categories.RANGED:
				return ranged(weapon, gear, levels);
			case Categories.MAGIC:
				return magic(weapon, gear, levels);
			default:
				return melee(weapon, gear, levels);
		}
	}

	private static double melee(Piece weapon, Map<Integer, Piece> gear, Levels levels)
	{
		ItemEquipmentStats w = weapon.stats;
		String n = weapon.name;
		// The weapon attacks with its best attack type; gear bonuses of that type count.
		boolean crushing = w.getAcrush() > w.getAslash() && w.getAcrush() > w.getAstab();
		boolean stabbing = !crushing && w.getAstab() > w.getAslash();
		int bonus = crushing ? sum(gear, ItemEquipmentStats::getAcrush)
			: stabbing ? sum(gear, ItemEquipmentStats::getAstab) : sum(gear, ItemEquipmentStats::getAslash);
		int strength = sum(gear, ItemEquipmentStats::getStr);
		int speed = speed(w, 4);
		// Piety; each Soulreaper axe soul stack (5 when attacking steadily) adds 6% like a prayer.
		int strengthPercent = 123 + (n.startsWith("soulreaper axe") ? 30 : 0);
		int voidPercent = wearsVoid(gear, "void melee helm", false) ? 110 : 100;
		int inquisitor = crushing ? inquisitorPermille(gear) : 0;

		double best = 0;
		for (int stance = 0; stance < 2; stance++)
		{
			// Accurate (+3 Attack) or aggressive (+3 Strength), whichever does more.
			int effectiveStrength = (levels.strength * strengthPercent / 100 + (stance == 1 ? 3 : 0) + 8) * voidPercent / 100;
			int effectiveAttack = (levels.attack * 120 / 100 + (stance == 0 ? 3 : 0) + 8) * voidPercent / 100;
			int max = (effectiveStrength * (strength + 64) + 320) / 640;
			long attack = (long) effectiveAttack * (bonus + 64);
			if (inquisitor > 0)
			{
				attack = attack * (1000 + inquisitor) / 1000;
				max = max * (1000 + inquisitor) / 1000;
			}
			double perTick;
			if (n.contains("scythe of vitur") && !n.contains("uncharged"))
			{
				// One hit per tile of the target's width, up to three, each with half the max of the one before.
				double damage = 0;
				for (int i = 0; i < Math.min(3, TARGET_SIZE); i++)
				{
					damage += hit(attack, DEFENCE_ROLL) * average(max >> i);
				}
				perTick = damage / speed;
			}
			else if (n.startsWith("osmumten's fang"))
			{
				// Rolls accuracy twice; damage is 15-85% of the max, which keeps the same mean.
				perTick = twoRolls(attack, DEFENCE_ROLL) * average(max) / speed;
			}
			else if (n.equals("obligator"))
			{
				// Charged Thrust (5 ticks): +40% max hit against large targets, best of two damage rolls.
				// Smash (3 ticks) has no effect.
				int thrustMax = TARGET_SIZE >= 3 ? max * 140 / 100 : TARGET_SIZE == 2 ? max * 120 / 100 : max;
				double thrust = hit(attack, DEFENCE_ROLL) * bestOf(thrustMax, 2) / 5;
				double smash = hit(attack, DEFENCE_ROLL) * average(max) / 3;
				perTick = Math.max(thrust, smash);
			}
			else if (n.startsWith("dual macuahuitl"))
			{
				// Two hitsplats splitting the max; the second only lands if the first did. Blood moon: each landed
				// splat has a 33% chance to make the next attack come a tick early.
				double p = hit(attack, DEFENCE_ROLL);
				double early = wearsMoonSet(gear, "blood moon") ? p * (1 - p) * 0.33 + p * p * (1 - 0.67 * 0.67) : 0;
				perTick = (p * average(max / 2) + p * p * average(max - max / 2)) / (speed - early);
			}
			else
			{
				perTick = hit(attack, DEFENCE_ROLL) * average(max) / speed;
			}
			best = Math.max(best, perTick);
		}
		return best;
	}

	private static double ranged(Piece weapon, Map<Integer, Piece> gear, Levels levels)
	{
		String n = weapon.name;
		int speed = Math.max(1, speed(weapon.stats, 5) - 1); // rapid
		double accuracy = 1;
		double damage = 1;
		if (n.startsWith("twisted bow"))
		{
			// Scales with the target's Magic level (capped at 250 outside raids).
			int m = Math.min(TARGET_MAGIC, 250);
			accuracy = Math.min(140, 140 + (3 * m - 10) / 100.0 - Math.pow(0.3 * m - 100, 2) / 100) / 100;
			damage = Math.min(250, 250 + (3 * m - 14) / 100.0 - Math.pow(0.3 * m - 140, 2) / 100) / 100;
		}
		if (n.startsWith("bow of faerdhinen"))
		{
			// Crystal armour: helm +5%/+2.5%, body +15%/+7.5%, legs +10%/+5% accuracy/damage.
			if (startsWith(gear, HEAD, "crystal helm"))
			{
				accuracy += 0.05;
				damage += 0.025;
			}
			if (startsWith(gear, BODY, "crystal body"))
			{
				accuracy += 0.15;
				damage += 0.075;
			}
			if (startsWith(gear, LEGS, "crystal legs"))
			{
				accuracy += 0.10;
				damage += 0.05;
			}
		}
		boolean eliteVoid = wearsVoid(gear, "void ranger helm", true);
		boolean anyVoid = eliteVoid || wearsVoid(gear, "void ranger helm", false);
		// The eclipse atlatl hits with the Strength level and melee strength bonus; ranged prayers still apply.
		boolean atlatl = n.startsWith("eclipse atlatl");
		int damageLevel = atlatl ? levels.strength : levels.ranged;
		int effectiveStrength = (int) ((damageLevel * 123 / 100 + 8) * (eliteVoid ? 1.125 : anyVoid ? 1.1 : 1));
		int effectiveAttack = (levels.ranged * 120 / 100 + 8) * (anyVoid ? 110 : 100) / 100;
		int strength;
		if (atlatl)
		{
			strength = sum(gear, ItemEquipmentStats::getStr);
		}
		else
		{
			// The owned ammo in the outfit, else the best the launcher can fire.
			strength = sum(gear, ItemEquipmentStats::getRstr) + (gear.containsKey(AMMO) ? 0 : ammoStrength(n));
		}
		int max = (int) (((effectiveStrength * (strength + 64) + 320) / 640) * damage);
		long attack = (long) (effectiveAttack * (sum(gear, ItemEquipmentStats::getArange) + 64) * accuracy);
		int arrows = n.startsWith("dark bow") ? 2 : 1;
		double p = hit(attack, DEFENCE_ROLL);
		// Eclipse: a fifth of landed atlatl hits burn for 10 damage, about 2 per landed hit.
		double burn = atlatl && wearsMoonSet(gear, "eclipse moon") ? p * 2 : 0;
		return (arrows * p * average(max) + burn) / speed;
	}

	private static double magic(Piece weapon, Map<Integer, Piece> gear, Levels levels)
	{
		String n = weapon.name;
		int lvl = levels.magic;
		int base;
		int speed;
		boolean powered = true;
		double accuracyBonus = 0;
		double damageBonus = 0;
		if (n.startsWith("tumeken's shadow"))
		{
			base = lvl / 3 + 1;
			speed = 5;
		}
		else if (n.contains("sanguinesti staff"))
		{
			base = lvl / 3;
			speed = 4;
		}
		else if (n.startsWith("trident of the swamp"))
		{
			base = lvl / 3 - 2;
			speed = 4;
		}
		else if (n.startsWith("trident of the seas"))
		{
			base = lvl / 3 - 5;
			speed = 4;
		}
		else if (n.startsWith("eye of ayak"))
		{
			base = lvl / 3 - 6;
			speed = 3;
		}
		else if (n.startsWith("warped sceptre"))
		{
			base = (8 * lvl + 96) / 37;
			speed = 4;
		}
		else
		{
			// Autocasting: the best Ancient spell on staves that cast them, else the best fire spell.
			powered = false;
			boolean ancients = n.startsWith("kodai wand") || n.contains("nightmare staff") && !n.startsWith("harmonised")
				|| n.startsWith("ancient sceptre") || n.startsWith("ancient staff") || n.endsWith("ancient sceptre")
				|| n.startsWith("blue moon spear");
			base = ancients ? ancientSpell(lvl) : fireSpell(lvl);
			speed = n.startsWith("harmonised nightmare staff") ? 4 : n.startsWith("twinflame staff") ? 6 : 5;
			if (n.startsWith("twinflame staff"))
			{
				accuracyBonus = 0.10;
				damageBonus = 0.10;
			}
			if (n.contains("smoke") && n.contains("staff"))
			{
				damageBonus = 0.10;
			}
		}
		if (base <= 0)
		{
			return 0;
		}
		// The shadow triples every worn magic attack and damage bonus, its own included (damage capped at +100%).
		int shadow = n.startsWith("tumeken's shadow") ? 3 : 1;
		boolean eliteVoid = wearsVoid(gear, "void mage helm", true);
		boolean anyVoid = eliteVoid || wearsVoid(gear, "void mage helm", false);
		double magicDamage = Math.min(1.0, sum(gear, s -> Math.round(s.getMdmg() * 10)) / 1000.0 * shadow)
			+ 0.04 // Augury
			+ (eliteVoid ? 0.05 : 0) + damageBonus;
		int max = (int) (base * (1 + magicDamage));
		int effectiveMagic = (int) (lvl * 125 / 100 * (anyVoid ? 1.45 : 1)) + (powered ? 2 : 0) + 9;
		long attack = (long) (effectiveMagic * (long) (sum(gear, ItemEquipmentStats::getAmagic) * shadow + 64)
			* (1 + accuracyBonus));
		double p = startsWith(gear, GLOVES, "confliction gauntlets") && !weapon.stats.isTwoHanded()
			? confliction(attack, MAGIC_DEFENCE_ROLL) : hit(attack, MAGIC_DEFENCE_ROLL);
		// Sanguinesti: a fifth of hits deal 8 extra damage.
		double extra = n.contains("sanguinesti staff") ? p * 0.2 * 8 : 0;
		if (!powered && n.startsWith("blue moon spear") && wearsMoonSet(gear, "blue moon") && ancientSpell(lvl) > 0)
		{
			// Frostweaver: a fifth of Ice spell casts give a free melee hit with the spear (no melee prayer up).
			extra += 0.2 * spearHit(gear, levels);
		}
		return (p * average(max) + extra) / speed;
	}

	/** Expected damage of one stab with the worn gear, without a melee prayer. */
	private static double spearHit(Map<Integer, Piece> gear, Levels levels)
	{
		int effectiveStrength = levels.strength + 3 + 8;
		int effectiveAttack = levels.attack + 8;
		int max = (effectiveStrength * (sum(gear, ItemEquipmentStats::getStr) + 64) + 320) / 640;
		long attack = (long) effectiveAttack * (sum(gear, ItemEquipmentStats::getAstab) + 64);
		return hit(attack, DEFENCE_ROLL) * average(max);
	}

	private static int ancientSpell(int lvl)
	{
		return lvl >= 94 ? 30 : lvl >= 82 ? 26 : lvl >= 70 ? 22 : lvl >= 58 ? 18 : 0;
	}

	private static int fireSpell(int lvl)
	{
		return lvl >= 95 ? 24 : lvl >= 75 ? 20 : lvl >= 59 ? 16 : lvl >= 35 ? 12 : lvl >= 13 ? 8 : 0;
	}

	private static final String[] ARROW_TIERS = {"bronze", "iron", "steel", "mithril", "adamant", "rune", "amethyst",
		"dragon"};
	// Bolts by metal tier; gem-tipped ones by the metal they're made from: opal and jade bronze, pearl iron, topaz
	// steel, sapphire and emerald mithril, ruby and diamond adamant, dragonstone and onyx runite.
	private static final String[][] BOLT_TIERS = {
		{"bronze", "opal", "jade", "blurite", "barbed"}, {"iron", "pearl"}, {"steel", "topaz", "red topaz"},
		{"mithril", "sapphire", "emerald"}, {"adamant", "ruby", "diamond"}, {"runite", "dragonstone", "onyx", "broad"},
	};

	/**
	 * Whether the launcher fires this ammo: arrows and bolts up to the launcher's tier, and the special ammo of a
	 * few launchers.
	 */
	static boolean fires(String weaponName, String ammoName)
	{
		String w = weaponName.toLowerCase();
		String a = ammoName.toLowerCase();
		if (a.contains("javelin"))
		{
			return w.contains("ballista");
		}
		if (a.contains("atlatl dart"))
		{
			return w.startsWith("eclipse atlatl");
		}
		if (a.startsWith("bolt rack"))
		{
			return w.startsWith("karil's crossbow");
		}
		if (a.startsWith("ascension bolts"))
		{
			return w.startsWith("ascension crossbow");
		}
		if (a.contains("antler bolts"))
		{
			return w.startsWith("hunters' sunlight crossbow");
		}
		if (a.startsWith("kebbit bolts"))
		{
			return w.startsWith("hunters' crossbow");
		}
		if (a.startsWith("bone bolts"))
		{
			return w.startsWith("dorgeshuun crossbow");
		}
		if (a.contains("ogre arrow") || a.contains("brutal arrow"))
		{
			return w.contains("ogre bow");
		}
		if (a.startsWith("training arrows"))
		{
			return w.startsWith("training bow");
		}
		if (a.contains("bolts"))
		{
			int tier = boltTier(a);
			return tier > 0 && tier <= crossbowTier(w);
		}
		if (a.contains("arrow"))
		{
			int tier = arrowTier(a);
			return tier > 0 && tier <= bowTier(w);
		}
		return false;
	}

	private static int boltTier(String ammo)
	{
		if (ammo.contains("dragon bolts"))
		{
			return BOLT_TIERS.length + 1;
		}
		if (ammo.startsWith("amethyst broad"))
		{
			return BOLT_TIERS.length;
		}
		for (int i = 0; i < BOLT_TIERS.length; i++)
		{
			for (String prefix : BOLT_TIERS[i])
			{
				if (ammo.startsWith(prefix + " "))
				{
					return i + 1;
				}
			}
		}
		return 0;
	}

	private static int crossbowTier(String weapon)
	{
		if (!weapon.contains("crossbow") || weapon.startsWith("dorgeshuun") || weapon.startsWith("hunters'")
			|| weapon.startsWith("karil's") || weapon.startsWith("ascension"))
		{
			return 0;
		}
		String[] metals = {"bronze", "iron", "steel", "mithril", "adamant", "rune"};
		for (int i = 0; i < metals.length; i++)
		{
			if (weapon.startsWith(metals[i]))
			{
				return i + 1;
			}
		}
		if (weapon.startsWith("blurite") || weapon.equals("crossbow") || weapon.startsWith("phoenix"))
		{
			return 1;
		}
		return BOLT_TIERS.length + 1; // dragon, armadyl, zaryte, dragon hunter
	}

	private static int arrowTier(String ammo)
	{
		if (ammo.startsWith("broad arrows") || ammo.startsWith("amethyst broad"))
		{
			return 6;
		}
		if (ammo.startsWith("ice arrows"))
		{
			return 1;
		}
		for (int i = 0; i < ARROW_TIERS.length; i++)
		{
			if (ammo.startsWith(ARROW_TIERS[i] + " arrow"))
			{
				return i + 1;
			}
		}
		return 0;
	}

	private static int bowTier(String weapon)
	{
		if (weapon.contains("crossbow") || !weapon.contains("bow") || weapon.startsWith("craw's")
			|| weapon.startsWith("webweaver") || weapon.startsWith("bow of faerdhinen") || weapon.startsWith("crystal bow")
			|| weapon.startsWith("training bow") || weapon.contains("ogre bow"))
		{
			return 0;
		}
		String[][] woods = {{"magic", "7"}, {"seercull", "7"}, {"yew", "6"}, {"maple", "5"}, {"willow", "4"},
			{"oak", "3"}, {"shortbow", "2"}, {"longbow", "2"}};
		for (String[] wood : woods)
		{
			if (weapon.startsWith(wood[0]))
			{
				return Integer.parseInt(wood[1]);
			}
		}
		return ARROW_TIERS.length; // twisted, dark, venator, scorching, 3rd age...
	}

	// The best arrows and bolts each launcher tier can fire, by name prefix: ranged strength.
	private static final String[][] BOWS = {
		{"magic", "55"}, {"yew", "49"}, {"maple", "31"}, {"willow", "22"}, {"oak", "16"}, {"shortbow", "10"},
		{"longbow", "10"},
	};
	private static final String[][] CROSSBOWS = {
		{"rune", "115"}, {"adamant", "100"}, {"mithril", "82"}, {"steel", "64"}, {"iron", "46"}, {"bronze", "10"},
		{"blurite", "46"}, {"dorgeshuun", "49"}, {"hunters' sunlight", "60"}, {"crossbow", "10"},
	};

	private static int ammoStrength(String weapon)
	{
		if (weapon.contains("blowpipe"))
		{
			return DARTS;
		}
		if (weapon.matches(".*(knife|dart|thrownaxe|chinchompa|javelin|salamander|atlatl).*")
			|| weapon.startsWith("bow of faerdhinen") || weapon.startsWith("crystal bow")
			|| weapon.startsWith("ascension crossbows") || weapon.startsWith("craw's bow")
			|| weapon.startsWith("webweaver bow"))
		{
			return 0; // thrown, or no ammo
		}
		if (weapon.contains("ballista"))
		{
			return JAVELINS;
		}
		String[][] tiers = weapon.contains("crossbow") ? CROSSBOWS : BOWS;
		for (String[] tier : tiers)
		{
			if (weapon.startsWith(tier[0]))
			{
				return Integer.parseInt(tier[1]);
			}
		}
		// Dragon, armadyl, zaryte and dragon hunter crossbows; twisted, dark, venator, scorching and 3rd age bows.
		return weapon.contains("crossbow") ? BOLTS : ARROWS;
	}

	/** Full void: the style's helm plus top, robe and gloves; elite if the top and robe are elite. */
	private static boolean wearsVoid(Map<Integer, Piece> gear, String helm, boolean elite)
	{
		if (!startsWith(gear, HEAD, helm) || !startsWith(gear, GLOVES, "void knight gloves"))
		{
			return false;
		}
		boolean eliteTop = startsWith(gear, BODY, "elite void top");
		boolean eliteRobe = startsWith(gear, LEGS, "elite void robe");
		if (elite)
		{
			return eliteTop && eliteRobe;
		}
		return (eliteTop || startsWith(gear, BODY, "void knight top"))
			&& (eliteRobe || startsWith(gear, LEGS, "void knight robe"));
	}

	/** The helm, chestplate and tassets of a moon set (broken pieces count). */
	private static boolean wearsMoonSet(Map<Integer, Piece> gear, String set)
	{
		return startsWith(gear, HEAD, set + " helm") && startsWith(gear, BODY, set + " chestplate")
			&& startsWith(gear, LEGS, set + " tassets");
	}

	/** Inquisitor's armour on crush: +0.5% accuracy and damage per piece, 2.5% for all three. */
	private static int inquisitorPermille(Map<Integer, Piece> gear)
	{
		int pieces = (startsWith(gear, HEAD, "inquisitor's") ? 1 : 0) + (startsWith(gear, BODY, "inquisitor's") ? 1 : 0)
			+ (startsWith(gear, LEGS, "inquisitor's") ? 1 : 0);
		return pieces == 3 ? 25 : pieces * 5;
	}

	private static boolean startsWith(Map<Integer, Piece> gear, int slot, String prefix)
	{
		Piece p = gear.get(slot);
		return p != null && p.name.startsWith(prefix);
	}

	private interface Stat
	{
		long of(ItemEquipmentStats s);
	}

	private static int sum(Map<Integer, Piece> gear, Stat stat)
	{
		long total = 0;
		for (Piece p : gear.values())
		{
			if (p != null && p.stats != null)
			{
				total += stat.of(p.stats);
			}
		}
		return (int) total;
	}

	private static int speed(ItemEquipmentStats w, int fallback)
	{
		return w.getAspeed() > 0 ? w.getAspeed() : fallback;
	}

	static double hit(long attack, long defence)
	{
		attack = Math.max(attack, 0);
		return attack > defence ? 1 - (defence + 2) / (2.0 * (attack + 1)) : attack / (2.0 * (defence + 1));
	}

	/** Two accuracy rolls against one defence roll, either succeeding (Osmumten's fang). */
	static double twoRolls(long attack, long defence)
	{
		double a = Math.max(attack, 0);
		double d = defence;
		return a >= d ? 1 - (d + 2) * (2 * d + 3) / (6 * (a + 1) * (a + 1)) : a * (4 * a + 5) / (6 * (a + 1) * (d + 1));
	}

	/** Confliction gauntlets: a magic attack after a miss rolls accuracy twice; long-run hit chance. */
	private static double confliction(long attack, long defence)
	{
		double p = hit(attack, defence);
		double p2 = twoRolls(attack, defence);
		return p2 / (1 - p + p2);
	}

	private static double average(int max)
	{
		return Math.max(max, 0) / 2.0;
	}

	/** Mean of the highest of k damage rolls from 0 to max. */
	private static double bestOf(int max, int k)
	{
		double total = 0;
		for (int i = 1; i <= max; i++)
		{
			total += 1 - Math.pow((double) i / (max + 1), k);
		}
		return total;
	}
}

