package com.smartbanksorter;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.BiFunction;
import java.util.function.Consumer;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/**
 * Item lookups for the category editor, from the game's item definitions and the bank.
 */
final class GameItems implements ItemLookup
{
	private static final int MAX_RESULTS = 40;
	// Matches gathered from the whole game before sorting them; a short search can match thousands.
	private static final int MAX_CANDIDATES = 400;

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	// The category the plugin sorts an item into, from its canonical ID and name. Client thread only.
	private final BiFunction<Integer, String, String> categoryOf;

	GameItems(Client client, ClientThread clientThread, ItemManager itemManager,
		BiFunction<Integer, String, String> categoryOf)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.categoryOf = categoryOf;
	}

	@Override
	public void search(String text, Consumer<List<Row>> done)
	{
		clientThread.invokeLater(() ->
		{
			List<Row> rows = searchNow(text.trim());
			SwingUtilities.invokeLater(() -> done.accept(rows));
		});
	}

	@Override
	public void describe(List<String> patterns, Consumer<List<Row>> done)
	{
		clientThread.invokeLater(() ->
		{
			Set<Integer> bank = bankItems();
			List<Row> rows = new ArrayList<>();
			patterns.forEach(p -> rows.add(describeNow(p, bank)));
			SwingUtilities.invokeLater(() -> done.accept(rows));
		});
	}

	@Override
	public void icon(int itemId, JLabel label)
	{
		itemManager.getImage(itemId).addTo(label);
	}

	private List<Row> searchNow(String text)
	{
		List<Row> rows = new ArrayList<>();
		if (text.isEmpty())
		{
			return rows;
		}
		String lower = text.toLowerCase();
		boolean wildcard = text.contains("*");
		Pattern glob = UserRules.glob(text);
		Predicate<String> matches = wildcard ? n -> glob.matcher(n).matches() : n -> n.toLowerCase().contains(lower);
		// Names starting with the search first, then alphabetical.
		Comparator<Row> order = Comparator.<Row>comparingInt(r -> r.name.toLowerCase().startsWith(lower) ? 0 : 1)
			.thenComparing(r -> r.name, String.CASE_INSENSITIVE_ORDER);

		Set<String> seen = new HashSet<>();
		Set<Integer> bank = bankItems();
		List<Row> banked = new ArrayList<>();
		for (int id : bank)
		{
			String name = itemManager.getItemComposition(id).getName();
			if (matches.test(name) && seen.add(MoveToMenu.movePattern(name).toLowerCase()))
			{
				banked.add(row(id, name, true));
			}
		}
		banked.sort(order);

		List<Row> others = new ArrayList<>();
		for (int id = 0; id < client.getItemCount() && others.size() < MAX_CANDIDATES; id++)
		{
			ItemComposition item = itemManager.getItemComposition(id);
			String name = item.getName();
			if (item.getNote() != -1 || item.getPlaceholderTemplateId() != -1 || "null".equals(name)
				|| !matches.test(name) || !seen.add(MoveToMenu.movePattern(name).toLowerCase()))
			{
				continue;
			}
			others.add(row(itemManager.canonicalize(id), name, false));
		}
		others.sort(order);

		Row group = ItemLookup.patternRow(text, banked, others);
		if (group != null)
		{
			rows.add(group);
		}
		rows.addAll(banked);
		rows.addAll(others);
		return rows.size() > MAX_RESULTS ? new ArrayList<>(rows.subList(0, MAX_RESULTS)) : rows;
	}

	// An item as a search result, with what a rule for it would say: doses and charges of it are one rule.
	private Row row(int id, String name, boolean inBank)
	{
		String pattern = MoveToMenu.movePattern(name);
		boolean doses = !pattern.equals(name);
		String category = categoryOf.apply(id, name);
		List<String> detail = new ArrayList<>();
		if (doses)
		{
			detail.add("All doses/charges");
		}
		detail.add("Now in " + category);
		if (inBank)
		{
			detail.add("In your bank");
		}
		return new Row(id, doses ? Doses.baseName(name) : name, pattern, String.join(" · ", detail), category, inBank);
	}

	private Row describeNow(String pattern, Set<Integer> bank)
	{
		if (pattern.matches("\\d+"))
		{
			int id = Integer.parseInt(pattern);
			if (id >= client.getItemCount())
			{
				return new Row(-1, "Item " + id, pattern, "No item has this ID", null, false);
			}
			return new Row(id, itemManager.getItemComposition(id).getName(), pattern, "Item ID " + id, categoryOf(id),
				bank.contains(id));
		}

		Pattern glob = UserRules.glob(pattern);
		int first = -1;
		int banked = 0;
		for (int id : bank)
		{
			if (glob.matcher(itemManager.getItemComposition(id).getName()).matches())
			{
				banked++;
				first = first < 0 ? id : first;
			}
		}
		if (first < 0)
		{
			first = firstInGame(glob);
		}

		// "Prayer potion(*", as Move to and the editor write for every dose of an item.
		String base = pattern.endsWith("(*") ? pattern.substring(0, pattern.length() - 2) : null;
		if (base != null && !base.contains("*"))
		{
			return new Row(first, base.trim(), pattern, banked > 0 ? "All doses/charges · In your bank"
				: "All doses/charges", first < 0 ? null : categoryOf(first), banked > 0);
		}
		if (pattern.contains("*"))
		{
			return new Row(first, pattern, pattern, banked == 0 ? "All matches · none in your bank"
				: "All matches · " + banked + " in your bank", null, banked > 0);
		}
		if (first < 0)
		{
			return new Row(-1, pattern, pattern, "No item has this name", null, false);
		}
		return new Row(first, itemManager.getItemComposition(first).getName(), pattern,
			banked > 0 ? "In your bank" : "Not in your bank", categoryOf(first), banked > 0);
	}

	private String categoryOf(int itemId)
	{
		int id = itemManager.canonicalize(itemId);
		return categoryOf.apply(id, itemManager.getItemComposition(id).getName());
	}

	private int firstInGame(Pattern glob)
	{
		for (int id = 0; id < client.getItemCount(); id++)
		{
			ItemComposition item = itemManager.getItemComposition(id);
			if (item.getNote() == -1 && item.getPlaceholderTemplateId() == -1 && glob.matcher(item.getName()).matches())
			{
				return id;
			}
		}
		return -1;
	}

	// The bank's items as the sorted bank shows them: placeholders as their items, no fillers.
	private Set<Integer> bankItems()
	{
		Set<Integer> ids = new LinkedHashSet<>();
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank != null)
		{
			for (Item item : bank.getItems())
			{
				if (item.getId() > 0 && item.getId() != ItemID.BANK_FILLER)
				{
					ids.add(itemManager.canonicalize(item.getId()));
				}
			}
		}
		return ids;
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Function;
import java.util.function.ToIntFunction;
import java.util.stream.Collectors;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Orders combat gear into outfits by damage. Each weapon gets an outfit: the pieces that give it the most
 * {@link DpsCalc damage} against a typical boss, from those the outfits before it left. Weapons go best first, by
 * the damage of their best outfit; ones the player can't wield yet go last. Pieces no outfit took follow, ranked by
 * what they'd add to the best outfit, then by stats. Without weapons, pieces rank by stats alone.
 * <p>
 * In column layout each outfit is one bank column read head to feet, under its weapon, so the first column is your
 * best setup. In row layout each outfit is one row instead (weapons, then shields, come first, to keep rows at 8).
 */
final class GearOrder
{
	/** What GearOrder needs to know about an item. */
	interface Gear<T>
	{
		ItemEquipmentStats stats(T item);

		String name(T item);

		/** GE price per item, the last tie-break. */
		long price(T item);

		/** {@link #upgradeRank} */
		int upgrade(T item);

		/** {@link WeaponLevels#rank} for this style */
		int weaponRank(T item);

		/** Level needed to wield it in this style's skill; 0 if none or unknown. */
		int wieldLevel(T item);

		/** Set-effect set name, or null. */
		String set(T item);
	}

	// Head-to-feet order of an outfit column.
	private static final EquipmentInventorySlot[] COLUMN_ORDER = {
		EquipmentInventorySlot.HEAD, EquipmentInventorySlot.CAPE, EquipmentInventorySlot.AMULET,
		EquipmentInventorySlot.BODY, EquipmentInventorySlot.SHIELD, EquipmentInventorySlot.LEGS,
		EquipmentInventorySlot.GLOVES, EquipmentInventorySlot.BOOTS, EquipmentInventorySlot.RING,
	};
	// Row layout: once tiers get this sparse, stop starting new rows and pack the rest.
	private static final int MIN_ROW_ITEMS = 3;

	private GearOrder()
	{
	}

	/**
	 * @param levels the player's levels, for damage and for which weapons they can wield
	 * @param columns lay outfits out as columns rather than rows
	 * @param pack pack each row of gear left, with no gaps
	 * @param bestOnly count only pieces that add damage towards keeping an outfit, so outfits made up from plain
	 * armour join the spare gear
	 * @return rows of cells, each starting on a new bank row; null cells are left empty
	 */
	static <T> List<List<T>> order(List<T> items, String category, Gear<T> gear, DpsCalc.Levels levels,
		Comparator<T> tiebreak, boolean columns, boolean pack, boolean bestOnly, int bankColumns)
	{
		Comparator<T> byStats = Comparator.comparingInt((T t) -> score(category, gear.stats(t))).reversed();
		Comparator<T> byPrice = Comparator.comparingLong(gear::price).reversed();
		// Equal scores: the piece that hits harder wins.
		Comparator<T> byOffence = Comparator.comparingInt((T t) -> offence(category, gear.stats(t))).reversed();
		Comparator<T> upgradesFirst = Comparator.comparingInt(gear::upgrade).reversed();
		Comparator<T> byScore = byStats.thenComparing(byOffence).thenComparing(upgradesFirst).thenComparing(byPrice)
			.thenComparing(tiebreak);

		List<T> weapons = new ArrayList<>();
		List<T> blessings = new ArrayList<>();
		List<T> other = new ArrayList<>();
		Map<Integer, List<T>> bySlot = new HashMap<>();
		for (T item : items)
		{
			ItemEquipmentStats e = gear.stats(item);
			if (e == null)
			{
				other.add(item);
			}
			else if (e.getSlot() == EquipmentInventorySlot.WEAPON.getSlotIdx())
			{
				weapons.add(item);
			}
			else if (e.getSlot() == EquipmentInventorySlot.AMMO.getSlotIdx())
			{
				blessings.add(item);
			}
			else
			{
				bySlot.computeIfAbsent(e.getSlot(), k -> new ArrayList<>()).add(item);
			}
		}
		// Gear in slots outside an outfit (e.g. ammo moved here by a custom rule) goes at the end.
		for (Map.Entry<Integer, List<T>> entry : new ArrayList<>(bySlot.entrySet()))
		{
			if (!inOrder(COLUMN_ORDER, entry.getKey()))
			{
				other.addAll(0, entry.getValue());
				bySlot.remove(entry.getKey());
			}
		}
		for (List<T> slotItems : bySlot.values())
		{
			slotItems.sort(byScore);
		}
		blessings.sort(byStats.thenComparing(byPrice).thenComparing(tiebreak));
		// Ranged ammo goes with the launchers that fire it; blessings suit any weapon.
		boolean ranged = Categories.RANGED.equals(category);

		Outfits<T> outfits = new Outfits<>(category, gear, levels, bySlot, ranged ? blessings : Collections.emptyList());
		Map<Integer, List<T>> grid = new HashMap<>();
		// Weapons without an outfit of their own, and gear no outfit took.
		List<T> spareWeapons = new ArrayList<>();
		List<T> spareGear = new ArrayList<>();
		if (!weapons.isEmpty())
		{
			outfits.keepSets(weapons);
			Function<T, String> keptSet = t -> outfits.keeps(gear.set(t)) ? gear.set(t) : null;
			// Weapons by the damage of their best outfit from everything owned; ones the player can't wield yet last.
			Map<T, Double> damage = new HashMap<>();
			for (T weapon : weapons)
			{
				damage.put(weapon, outfits.damage(weapon, outfits.best(weapon, Collections.emptySet())));
			}
			int skillLevel = skillLevel(category, levels);
			weapons.sort(Comparator.comparing((T w) -> gear.wieldLevel(w) > skillLevel)
				.thenComparing(Comparator.comparingDouble((T w) -> round(damage.get(w))).reversed())
				.thenComparing(Comparator.comparingInt(gear::weaponRank).reversed())
				.thenComparing(byStats).thenComparing(upgradesFirst).thenComparing(byPrice).thenComparing(tiebreak));

			// Each weapon, in that order, gets the best outfit from what's left.
			Set<T> used = new HashSet<>();
			for (int i = 0; i < weapons.size(); i++)
			{
				for (Map.Entry<Integer, T> piece : outfits.best(weapons.get(i), used).entrySet())
				{
					List<T> slotColumn = grid.computeIfAbsent(piece.getKey(), k -> new ArrayList<>());
					while (slotColumn.size() <= i)
					{
						slotColumn.add(null);
					}
					slotColumn.set(i, piece.getValue());
					used.add(piece.getValue());
				}
			}
			// A weapon keeps its outfit only if at least half its slots are filled (best outfits only: by pieces that
			// add damage, through offensive stats or an effect), or it wears a set (Dharok's greataxe in Dharok's); the
			// strongest keeps any it has. The others go after the outfits, and their pieces join the spare gear.
			for (int i = weapons.size() - 1; i >= 0; i--)
			{
				int column = i;
				T weapon = weapons.get(i);
				Map<Integer, T> outfit = new HashMap<>();
				grid.forEach((slot, c) ->
				{
					if (column < c.size() && c.get(column) != null)
					{
						outfit.put(slot, c.get(column));
					}
				});
				double full = round(outfits.damage(weapon, outfit));
				int adding = 0;
				for (EquipmentInventorySlot slot : COLUMN_ORDER)
				{
					Map<Integer, T> without = new HashMap<>(outfit);
					T piece = without.remove(slot.getSlotIdx());
					if (piece != null && (!bestOnly || offence(category, gear.stats(piece)) > 0
						|| round(outfits.damage(weapon, without)) < full))
					{
						adding++;
					}
				}
				boolean wearsSet = outfit.values().stream().map(keptSet).filter(Objects::nonNull)
					.collect(Collectors.groupingBy(set -> set, Collectors.counting())).values().stream().anyMatch(n -> n >= 2);
				int slots = COLUMN_ORDER.length - (gear.stats(weapon).isTwoHanded() ? 1 : 0);
				if (i == 0 ? !outfit.isEmpty() : adding * 2 >= slots || wearsSet)
				{
					continue;
				}
				spareWeapons.add(0, weapons.remove(i));
				for (List<T> slotColumn : grid.values())
				{
					if (column < slotColumn.size())
					{
						used.remove(slotColumn.remove(column));
					}
				}
			}
			blessings.removeIf(used::contains);

			// The rest: by what they'd add to the best outfit, then by stats.
			T bestWeapon = weapons.isEmpty() ? spareWeapons.get(0) : weapons.get(0);
			Map<Integer, T> best = outfits.best(bestWeapon, Collections.emptySet());
			Map<Integer, List<T>> rest = new HashMap<>();
			for (Map.Entry<Integer, List<T>> entry : bySlot.entrySet())
			{
				List<T> left = new ArrayList<>();
				for (T item : entry.getValue())
				{
					if (!used.contains(item))
					{
						left.add(item);
					}
				}
				Map<T, Double> added = new HashMap<>();
				for (T item : left)
				{
					Map<Integer, T> swapped = new HashMap<>(best);
					swapped.put(entry.getKey(), item);
					added.put(item, round(outfits.damage(bestWeapon, swapped)));
				}
				left.sort(Comparator.comparingDouble((T t) -> added.get(t)).reversed().thenComparing(byScore));
				rest.put(entry.getKey(), left);
			}
			spareGear.addAll(spareGear(rest, keptSet));
		}
		else
		{
			grid = assignTiers(bySlot, COLUMN_ORDER, gear::set);
		}

		List<List<T>> rows = new ArrayList<>();
		int tiers = weapons.size();
		for (List<T> slotColumn : grid.values())
		{
			tiers = Math.max(tiers, slotColumn.size());
		}

		if (columns)
		{
			// Blocks of up to bankColumns outfits side by side, each column under its weapon and the ammo it fires.
			// Blessings follow the first row of weapons; spare ammo follows the outfits. Either goes after weapons with
			// no outfit when no weapon has one.
			boolean anyWeapons = !weapons.isEmpty() || !spareWeapons.isEmpty();
			if (!anyWeapons && !blessings.isEmpty())
			{
				rows.add(blessings);
			}
			for (int first = 0; first < tiers; first += bankColumns)
			{
				int last = Math.min(tiers, first + bankColumns);
				if (first < weapons.size())
				{
					rows.add(new ArrayList<>(weapons.subList(first, Math.min(weapons.size(), last))));
					if (first == 0 && !ranged && !blessings.isEmpty())
					{
						rows.add(blessings);
					}
				}
				if (pack)
				{
					// Each column's ammo and gear stacked straight under its weapon, no gaps.
					List<List<T>> stacks = new ArrayList<>();
					int height = 0;
					for (int tier = first; tier < last; tier++)
					{
						List<T> stack = outfit(grid, tier);
						stacks.add(stack);
						height = Math.max(height, stack.size());
					}
					for (int r = 0; r < height; r++)
					{
						List<T> row = new ArrayList<>();
						for (List<T> stack : stacks)
						{
							row.add(r < stack.size() ? stack.get(r) : null);
						}
						rows.add(trimmed(row));
					}
				}
				else
				{
					// One row per slot, so each piece lines up with the same slot of the other outfits.
					List<EquipmentInventorySlot> slots = new ArrayList<>();
					slots.add(EquipmentInventorySlot.AMMO);
					slots.addAll(Arrays.asList(COLUMN_ORDER));
					for (EquipmentInventorySlot slot : slots)
					{
						List<T> slotColumn = grid.getOrDefault(slot.getSlotIdx(), Collections.emptyList());
						List<T> row = new ArrayList<>();
						for (int tier = first; tier < last && tier < slotColumn.size(); tier++)
						{
							row.add(slotColumn.get(tier));
						}
						if (row.stream().anyMatch(Objects::nonNull))
						{
							rows.add(row);
						}
					}
				}
			}
			if (!spareWeapons.isEmpty())
			{
				rows.add(spareWeapons);
			}
			if (!spareGear.isEmpty())
			{
				rows.add(spareGear);
			}
			if (anyWeapons && (ranged || weapons.isEmpty()) && !blessings.isEmpty())
			{
				rows.add(blessings);
			}
			if (!other.isEmpty())
			{
				rows.add(other);
			}
			return rows;
		}

		// Row layout: one outfit per row, its weapon first, then its ammo and gear head to feet. A full outfit is
		// longer than a bank row, so it carries on in the next. Weapons without an outfit, gear no outfit took,
		// blessings and spare ammo follow.
		if (weapons.isEmpty())
		{
			// No weapons: shields and blessings first, so each outfit fits in one row.
			List<T> hands = new ArrayList<>(blessings);
			for (T shield : grid.getOrDefault(EquipmentInventorySlot.SHIELD.getSlotIdx(), Collections.emptyList()))
			{
				if (shield != null)
				{
					hands.add(shield);
				}
			}
			if (!hands.isEmpty())
			{
				rows.add(hands);
			}
			grid.remove(EquipmentInventorySlot.SHIELD.getSlotIdx());
			blessings.clear();
		}
		List<T> tail = new ArrayList<>();
		for (int tier = 0; tier < tiers; tier++)
		{
			List<T> row = outfit(grid, tier);
			if (tier < weapons.size())
			{
				row.add(0, weapons.get(tier));
				for (int i = 0; i < row.size(); i += bankColumns)
				{
					rows.add(new ArrayList<>(row.subList(i, Math.min(row.size(), i + bankColumns))));
				}
			}
			else if (tail.isEmpty() && row.size() >= MIN_ROW_ITEMS)
			{
				rows.add(row);
			}
			else
			{
				tail.addAll(row);
			}
		}
		tail.addAll(spareWeapons);
		tail.addAll(spareGear);
		tail.addAll(blessings);
		tail.addAll(other);
		if (!tail.isEmpty())
		{
			rows.add(tail);
		}
		return rows;
	}

	/** An outfit's ammo and gear, head to feet, without gaps. */
	private static <T> List<T> outfit(Map<Integer, List<T>> grid, int tier)
	{
		List<T> pieces = new ArrayList<>();
		List<EquipmentInventorySlot> slots = new ArrayList<>();
		slots.add(EquipmentInventorySlot.AMMO);
		slots.addAll(Arrays.asList(COLUMN_ORDER));
		for (EquipmentInventorySlot slot : slots)
		{
			List<T> slotColumn = grid.get(slot.getSlotIdx());
			if (slotColumn != null && tier < slotColumn.size() && slotColumn.get(tier) != null)
			{
				pieces.add(slotColumn.get(tier));
			}
		}
		return pieces;
	}

	private static <T> List<T> trimmed(List<T> row)
	{
		int end = row.size();
		while (end > 0 && row.get(end - 1) == null)
		{
			end--;
		}
		return new ArrayList<>(row.subList(0, end));
	}

	/**
	 * Finds each weapon's best outfit: per slot, the piece that adds the most damage, in two passes so pieces that
	 * work together (accuracy and strength) settle. Pieces that add no damage are chosen by stats, so defence and
	 * prayer still fill empty slots.
	 * <p>
	 * Owned sets (two or more pieces of one {@link Gear#set}) stay together only if their bonus pays: for some weapon,
	 * wearing the set beats the best outfit of single pieces. Those go into an outfit whole, their best piece per
	 * slot, or not at all. Weapons pick in order of strength, so such a set goes to the strongest weapon it does the
	 * most for (Blue moon armour with the eye of Ayak), else its own weapon (Dharok's greataxe) wears it. The pieces
	 * of other sets are single pieces like any other. Ranged weapons also take the strongest owned ammo they can fire.
	 */
	private static final class Outfits<T>
	{
		private final String category;
		private final Gear<T> gear;
		private final DpsCalc.Levels levels;
		private final Map<Integer, List<T>> bySlot;
		private final Map<T, DpsCalc.Piece> pieces = new HashMap<>();
		// Owned sets, members best first.
		private final Map<String, List<T>> sets = new LinkedHashMap<>();
		// The owned sets kept together, see keepSets.
		private final Set<String> kept = new HashSet<>();
		// Ranged ammo, best first.
		private final List<T> ammo;
		// Per slot, the pieces sorted by each stat damage depends on, then the pieces with modelled effects.
		private final Map<Integer, List<List<T>>> byKey = new HashMap<>();
		private static final int SHORTLIST = 6;
		// Pieces per slot tried in pairs.
		private static final int PAIRS = 3;

		Outfits(String category, Gear<T> gear, DpsCalc.Levels levels, Map<Integer, List<T>> bySlot, List<T> ammo)
		{
			this.category = category;
			this.gear = gear;
			this.levels = levels;
			this.bySlot = bySlot;
			this.ammo = ammo;
			for (EquipmentInventorySlot slot : COLUMN_ORDER)
			{
				for (T item : bySlot.getOrDefault(slot.getSlotIdx(), Collections.emptyList()))
				{
					String set = gear.set(item);
					if (set != null)
					{
						sets.computeIfAbsent(set, k -> new ArrayList<>()).add(item);
					}
				}
			}
			sets.values().removeIf(members -> members.size() < 2);
			shortlist();
		}

		/**
		 * Keeps together the owned sets whose bonus pays: for some weapon, wearing the set does more damage than the
		 * best outfit of single pieces, theirs included. A set whose own weapon is owned is kept too, as not every
		 * set effect is modelled (Dharok's, Verac's...). The other sets' pieces are single pieces from then on.
		 */
		void keepSets(List<T> weapons)
		{
			Set<String> keep = new HashSet<>();
			for (T weapon : weapons)
			{
				if (sets.containsKey(gear.set(weapon)))
				{
					keep.add(gear.set(weapon));
				}
			}
			for (String name : sets.keySet())
			{
				for (T weapon : keep.contains(name) ? Collections.<T>emptyList() : weapons)
				{
					Map<Integer, T> set = block(name, weapon, Collections.emptySet());
					if (set == null)
					{
						continue;
					}
					Map<Integer, T> base = ammoFor(weapon, Collections.emptySet());
					set.putAll(base);
					if (round(damage(weapon, fill(weapon, set, Collections.emptySet())))
						> round(damage(weapon, fill(weapon, base, Collections.emptySet()))))
					{
						keep.add(name);
						break;
					}
				}
			}
			kept.addAll(keep);
			shortlist();
		}

		boolean keeps(String set)
		{
			return set != null && kept.contains(set);
		}

		// Per slot, the pieces sorted by each stat damage depends on, then the pieces with modelled effects; the kept
		// sets' pieces aren't single pieces.
		private void shortlist()
		{
			byKey.clear();
			List<ToIntFunction<ItemEquipmentStats>> keys = Arrays.asList(ItemEquipmentStats::getAstab,
				ItemEquipmentStats::getAslash, ItemEquipmentStats::getAcrush, ItemEquipmentStats::getArange,
				ItemEquipmentStats::getAmagic, ItemEquipmentStats::getStr, ItemEquipmentStats::getRstr,
				e -> Math.round(e.getMdmg() * 10), e -> score(category, e));
			for (Map.Entry<Integer, List<T>> entry : bySlot.entrySet())
			{
				List<List<T>> lists = new ArrayList<>();
				for (ToIntFunction<ItemEquipmentStats> key : keys)
				{
					List<T> sorted = new ArrayList<>();
					for (T item : entry.getValue())
					{
						if (!inOwnedSet(item))
						{
							sorted.add(item);
						}
					}
					sorted.sort(Comparator.comparingInt((T t) -> key.applyAsInt(gear.stats(t))).reversed());
					lists.add(sorted);
				}
				List<T> effects = new ArrayList<>();
				for (T item : entry.getValue())
				{
					String name = gear.name(item).toLowerCase();
					if (!inOwnedSet(item) && (name.startsWith("crystal") || name.contains("void")
						|| name.startsWith("confliction") || name.startsWith("inquisitor's")))
					{
						effects.add(item);
					}
				}
				lists.add(effects);
				byKey.put(entry.getKey(), lists);
			}
		}

		/**
		 * The unused pieces of a slot worth trying: the best few still unused by each stat damage depends on, the
		 * best few by stats overall, and pieces with an effect DpsCalc models. Keeps the search fast in big banks;
		 * an unused piece outside every list is beaten on every stat that matters by one that's in it.
		 */
		private Set<T> candidates(int slot, Set<T> used)
		{
			Set<T> keep = new LinkedHashSet<>();
			List<List<T>> lists = byKey.getOrDefault(slot, Collections.emptyList());
			for (int k = 0; k < lists.size(); k++)
			{
				boolean effects = k == lists.size() - 1;
				int taken = 0;
				for (T item : lists.get(k))
				{
					if (!effects && taken >= SHORTLIST)
					{
						break;
					}
					if (!used.contains(item))
					{
						keep.add(item);
						taken++;
					}
				}
			}
			return keep;
		}

		/** The best outfit for the weapon from pieces not in {@code used}, by slot. */
		// The strongest unused ammo the weapon fires, if any.
		private Map<Integer, T> ammoFor(T weapon, Set<T> used)
		{
			Map<Integer, T> base = new HashMap<>();
			for (T a : ammo)
			{
				if (!used.contains(a) && DpsCalc.fires(gear.name(weapon), gear.name(a)))
				{
					base.put(EquipmentInventorySlot.AMMO.getSlotIdx(), a);
					break;
				}
			}
			return base;
		}

		Map<Integer, T> best(T weapon, Set<T> used)
		{
			Map<Integer, T> base = ammoFor(weapon, used);
			String own = gear.set(weapon);
			if (keeps(own))
			{
				Map<Integer, T> set = block(own, weapon, used);
				if (set != null)
				{
					set.putAll(base);
					return fill(weapon, set, used);
				}
			}
			Map<Integer, T> best = fill(weapon, base, used);
			double bestDamage = round(damage(weapon, best));
			for (String name : kept)
			{
				Map<Integer, T> set = block(name, weapon, used);
				if (set != null)
				{
					set.putAll(base);
					// Quick check: the set swapped into the current best outfit. Only search around it if it helps, or
					// does as much with more strength or accuracy (not just defence: Dharok's stays with its greataxe).
					Map<Integer, T> swapped = new HashMap<>(best);
					swapped.putAll(set);
					double quick = round(damage(weapon, swapped));
					if (quick < bestDamage || quick == bestDamage && !strongerOutfit(swapped, best))
					{
						continue;
					}
					Map<Integer, T> withSet = fill(weapon, set, used);
					double d = round(damage(weapon, withSet));
					if (d > bestDamage || d == bestDamage && strongerOutfit(withSet, best))
					{
						best = withSet;
						bestDamage = d;
					}
				}
			}
			return best;
		}

		double damage(T weapon, Map<Integer, T> outfit)
		{
			Map<Integer, DpsCalc.Piece> worn = new HashMap<>();
			worn.put(EquipmentInventorySlot.WEAPON.getSlotIdx(), piece(weapon));
			for (Map.Entry<Integer, T> e : outfit.entrySet())
			{
				worn.put(e.getKey(), piece(e.getValue()));
			}
			return DpsCalc.perTick(category, worn, levels);
		}

		/** The set's best unused piece per slot the weapon leaves free, or null if fewer than two are left. */
		private Map<Integer, T> block(String name, T weapon, Set<T> used)
		{
			boolean twoHanded = gear.stats(weapon).isTwoHanded();
			Map<Integer, T> set = new HashMap<>();
			for (T item : sets.get(name))
			{
				int slot = gear.stats(item).getSlot();
				if (!used.contains(item) && !(twoHanded && slot == EquipmentInventorySlot.SHIELD.getSlotIdx()))
				{
					set.putIfAbsent(slot, item);
				}
			}
			return set.size() >= 2 ? set : null;
		}

		// More offence over the whole outfit.
		private boolean strongerOutfit(Map<Integer, T> outfit, Map<Integer, T> than)
		{
			return total(outfit, e -> offence(category, e)) > total(than, e -> offence(category, e));
		}

		private int total(Map<Integer, T> outfit, ToIntFunction<ItemEquipmentStats> stat)
		{
			return outfit.values().stream().mapToInt(t -> stat.applyAsInt(gear.stats(t))).sum();
		}

		private boolean betterStats(T item, T than)
		{
			int offence = Integer.compare(offence(category, gear.stats(item)), offence(category, gear.stats(than)));
			return offence > 0 || offence == 0 && score(category, gear.stats(item)) > score(category, gear.stats(than));
		}

		private boolean inOwnedSet(T item)
		{
			return keeps(gear.set(item));
		}

		/** Fills the free slots of {@code fixed} with the single pieces that add the most. */
		private Map<Integer, T> fill(T weapon, Map<Integer, T> fixed, Set<T> used)
		{
			Map<Integer, T> outfit = new HashMap<>(fixed);
			boolean twoHanded = gear.stats(weapon).isTwoHanded();
			for (int pass = 0; pass < 2; pass++)
			{
				for (EquipmentInventorySlot slot : COLUMN_ORDER)
				{
					int idx = slot.getSlotIdx();
					if (fixed.containsKey(idx) || twoHanded && slot == EquipmentInventorySlot.SHIELD)
					{
						continue;
					}
					outfit.remove(idx);
					double bestDamage = round(damage(weapon, outfit));
					T bestPiece = null;
					for (T item : candidates(idx, used))
					{
						if (used.contains(item) || inOwnedSet(item))
						{
							continue;
						}
						outfit.put(idx, item);
						double d = round(damage(weapon, outfit));
						// Same damage: the better offence wins (it may count once a potion boosts the level), then the
						// better stats; any piece beats an empty slot.
						if (d > bestDamage || d == bestDamage && (bestPiece == null || betterStats(item, bestPiece)))
						{
							bestDamage = d;
							bestPiece = item;
						}
					}
					if (bestPiece == null)
					{
						outfit.remove(idx);
					}
					else
					{
						outfit.put(idx, bestPiece);
					}
				}
			}
			pairUp(weapon, fixed, outfit, used);
			return outfit;
		}

		/**
		 * One slot at a time misses strength pieces that only raise the max hit together: Fire cape and Berserker
		 * ring beat Ardougne cloak and Brimstone ring, but neither swap does alone. Tries the strongest few pieces of
		 * each two free slots together, keeping any pair that adds damage.
		 */
		private void pairUp(T weapon, Map<Integer, T> fixed, Map<Integer, T> outfit, Set<T> used)
		{
			boolean twoHanded = gear.stats(weapon).isTwoHanded();
			List<Integer> free = new ArrayList<>();
			Map<Integer, List<T>> strongest = new HashMap<>();
			for (EquipmentInventorySlot slot : COLUMN_ORDER)
			{
				int idx = slot.getSlotIdx();
				if (fixed.containsKey(idx) || twoHanded && slot == EquipmentInventorySlot.SHIELD)
				{
					continue;
				}
				List<T> pieces = new ArrayList<>();
				List<List<T>> lists = byKey.getOrDefault(idx, Collections.emptyList());
				for (T item : lists.isEmpty() ? Collections.<T>emptyList() : lists.get(strengthKey()))
				{
					if (pieces.size() >= PAIRS)
					{
						break;
					}
					if (!used.contains(item) && !inOwnedSet(item))
					{
						pieces.add(item);
					}
				}
				if (!pieces.isEmpty())
				{
					free.add(idx);
					strongest.put(idx, pieces);
				}
			}
			double current = round(damage(weapon, outfit));
			boolean improved = true;
			for (int pass = 0; improved && pass < 2; pass++)
			{
				improved = false;
				for (int i = 0; i < free.size(); i++)
				{
					for (int j = i + 1; j < free.size(); j++)
					{
						int a = free.get(i);
						int b = free.get(j);
						T oldA = outfit.get(a);
						T oldB = outfit.get(b);
						for (T x : strongest.get(a))
						{
							for (T y : strongest.get(b))
							{
								if (x == oldA || y == oldB)
								{
									continue;
								}
								outfit.put(a, x);
								outfit.put(b, y);
								double d = round(damage(weapon, outfit));
								if (d > current)
								{
									current = d;
									oldA = x;
									oldB = y;
									improved = true;
								}
							}
						}
						restore(outfit, a, oldA);
						restore(outfit, b, oldB);
					}
				}
			}
		}

		/** Index into {@link #byKey}'s lists (see the keys in the constructor) of the stat the max hit grows with. */
		private int strengthKey()
		{
			switch (category)
			{
				case Categories.RANGED:
					return 6;
				case Categories.MAGIC:
					return 7;
				default:
					return 5;
			}
		}

		private static <V> void restore(Map<Integer, V> outfit, int slot, V piece)
		{
			if (piece == null)
			{
				outfit.remove(slot);
			}
			else
			{
				outfit.put(slot, piece);
			}
		}

		private DpsCalc.Piece piece(T item)
		{
			return pieces.computeIfAbsent(item, i -> new DpsCalc.Piece(gear.name(i), gear.stats(i)));
		}
	}

	// Damage compared to 9 decimals, so float noise doesn't decide between equal pieces.
	private static double round(double damage)
	{
		return Math.round(damage * 1e9) / 1e9;
	}

	private static int skillLevel(String category, DpsCalc.Levels levels)
	{
		switch (category)
		{
			case Categories.RANGED:
				return levels.ranged;
			case Categories.MAGIC:
				return levels.magic;
			default:
				return levels.attack;
		}
	}

	/**
	 * Gear no outfit took, packed: owned sets first, each kept together head to feet, then the other pieces slot by
	 * slot head to feet, each slot in the order given.
	 */
	private static <T> List<T> spareGear(Map<Integer, List<T>> bySlot, Function<T, String> set)
	{
		Map<String, List<T>> sets = new LinkedHashMap<>();
		for (EquipmentInventorySlot slot : COLUMN_ORDER)
		{
			for (T item : bySlot.getOrDefault(slot.getSlotIdx(), Collections.emptyList()))
			{
				String name = set.apply(item);
				if (name != null)
				{
					sets.computeIfAbsent(name, k -> new ArrayList<>()).add(item);
				}
			}
		}
		List<T> packed = new ArrayList<>();
		sets.values().stream().filter(pieces -> pieces.size() >= 2).forEach(packed::addAll);
		for (EquipmentInventorySlot slot : COLUMN_ORDER)
		{
			for (T item : bySlot.getOrDefault(slot.getSlotIdx(), Collections.emptyList()))
			{
				if (!packed.contains(item))
				{
					packed.add(item);
				}
			}
		}
		return packed;
	}

	/**
	 * Gives every piece a tier (outfit index). Pieces are ranked within their slot, except that two or more
	 * owned pieces of a set (by {@code set}) share one tier: that of the set's best piece. A set wins ties
	 * with single pieces, since set pieces are only strong together.
	 *
	 * @param bySlot items per slot, best first
	 * @return per slot, the item at each tier; null where that outfit has nothing for the slot
	 */
	private static <T> Map<Integer, List<T>> assignTiers(Map<Integer, List<T>> bySlot, EquipmentInventorySlot[] order,
		Function<T, String> set)
	{
		final class Unit
		{
			final Map<Integer, T> pieces = new LinkedHashMap<>();
			int rank = Integer.MAX_VALUE;
		}

		Map<String, Unit> sets = new LinkedHashMap<>();
		List<Unit> units = new ArrayList<>();
		for (EquipmentInventorySlot slot : order)
		{
			List<T> slotItems = bySlot.getOrDefault(slot.getSlotIdx(), Collections.emptyList());
			for (int rank = 0; rank < slotItems.size(); rank++)
			{
				T item = slotItems.get(rank);
				String setName = set.apply(item);
				Unit unit = setName == null ? null : sets.computeIfAbsent(setName, k -> new Unit());
				// A second piece for a slot the set already fills (e.g. another void helm) stands alone.
				if (unit == null || unit.pieces.containsKey(slot.getSlotIdx()))
				{
					unit = new Unit();
					units.add(unit);
				}
				unit.pieces.put(slot.getSlotIdx(), item);
				unit.rank = Math.min(unit.rank, rank);
			}
		}
		units.addAll(sets.values());
		units.sort(Comparator.comparingInt((Unit u) -> u.rank).thenComparing(u -> u.pieces.size() < 2));

		Map<Integer, List<T>> grid = new HashMap<>();
		for (Unit unit : units)
		{
			int tier = 0;
			while (occupied(grid, unit.pieces.keySet(), tier))
			{
				tier++;
			}
			for (Map.Entry<Integer, T> piece : unit.pieces.entrySet())
			{
				List<T> slotColumn = grid.computeIfAbsent(piece.getKey(), k -> new ArrayList<>());
				while (slotColumn.size() <= tier)
				{
					slotColumn.add(null);
				}
				slotColumn.set(tier, piece.getValue());
			}
		}
		return grid;
	}

	private static <T> boolean occupied(Map<Integer, List<T>> grid, Iterable<Integer> slots, int tier)
	{
		for (int slot : slots)
		{
			List<T> slotColumn = grid.get(slot);
			if (slotColumn != null && tier < slotColumn.size() && slotColumn.get(tier) != null)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean inOrder(EquipmentInventorySlot[] order, int slotIdx)
	{
		for (EquipmentInventorySlot slot : order)
		{
			if (slot.getSlotIdx() == slotIdx)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Breaks ties between pieces with the same stats; higher goes first. An untradeable piece with a tradeable
	 * one's stats is its upgrade (blood fury) or a locked or cosmetic copy. Max cape versions and the blessed quiver
	 * add perks to an untradeable cape with the same stats.
	 */
	static int upgradeRank(String name, boolean tradeable)
	{
		String lower = name.toLowerCase();
		if (lower.endsWith("max cape") || lower.startsWith("blessed dizana's quiver"))
		{
			return 2;
		}
		return tradeable ? 0 : 1;
	}

	/**
	 * How good a piece is for the given combat style. Damage bonuses dominate; defence breaks ties
	 * between pure-defence pieces (e.g. rune vs dragon platebody).
	 */
	static int score(String category, ItemEquipmentStats e)
	{
		if (e == null)
		{
			return 0;
		}
		// Scaled by 20 so small defence differences (lunar vs beacon ring) aren't lost to rounding:
		// offence + prayer + average defence / 4.
		int defenceSum = e.getDstab() + e.getDslash() + e.getDcrush() + e.getDmagic() + e.getDrange();
		int offence;
		switch (category)
		{
			case Categories.RANGED:
				offence = 60 * e.getRstr() + 20 * e.getArange();
				break;
			case Categories.MAGIC:
				offence = Math.round(60 * e.getMdmg()) + 20 * e.getAmagic();
				break;
			default:
				offence = 60 * e.getStr() + 20 * Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush()));
		}
		return offence + 20 * e.getPrayer() + defenceSum;
	}

	/**
	 * Offensive value for one style only; zero or less means the piece does nothing for that style.
	 */
	static int offence(String category, ItemEquipmentStats e)
	{
		switch (category)
		{
			case Categories.RANGED:
				return 3 * e.getRstr() + e.getArange();
			case Categories.MAGIC:
				return Math.round(3 * e.getMdmg()) + e.getAmagic();
			default:
				int attack = Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush()));
				return 3 * e.getStr() + attack;
		}
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.function.Predicate;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Point;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemEquipmentStats;

class ItemCopies
{
	// How faded the bank draws placeholders.
	private static final int PLACEHOLDER_OPACITY = 120;

	private final Function<Slot, ItemEquipmentStats> equipmentOf;
	// Spare empty-slot widgets the bank interface already has past the last item. Copies reuse these, like
	// core Bank Tags layouts do for duplicates: the game treats them as real bank slots, so it builds their
	// menus itself, and onMenuOptionClicked points the click at the real item's slot.
	private List<Widget> spares = new ArrayList<>();
	// Copy widget's child index -> the real item's bank slot index.
	private final Map<Integer, Integer> copyTargets = new HashMap<>();
	// Child index of a spare widget showing a not-owned item -> that item.
	private final Map<Integer, Slot> ghosts = new HashMap<>();

	ItemCopies(Function<Slot, ItemEquipmentStats> equipmentOf)
	{
		this.equipmentOf = equipmentOf;
	}

	void setSpares(List<Widget> spares)
	{
		this.spares = spares;
	}

	void clearTargets()
	{
		copyTargets.clear();
		ghosts.clear();
	}

	boolean isCopy(Widget w)
	{
		return copyTargets.containsKey(w.getIndex()) || ghosts.containsKey(w.getIndex());
	}

	/**
	 * The not-owned item drawn under the mouse, or null.
	 *
	 * @param container the bank's item container, whose visible area clips the items
	 */
	Slot ghostAt(Point mouse, Widget container)
	{
		if (mouse == null || container == null || !container.getBounds().contains(mouse.getX(), mouse.getY()))
		{
			return null;
		}
		for (Widget w : spares)
		{
			Slot ghost = ghosts.get(w.getIndex());
			if (ghost != null && !w.isHidden() && w.getBounds().contains(mouse.getX(), mouse.getY()))
			{
				return ghost;
			}
		}
		return null;
	}

	void hideFrom(int from)
	{
		for (int i = from; i < spares.size(); i++)
		{
			spares.get(i).setHidden(true);
		}
	}

	void clear()
	{
		spares = new ArrayList<>();
		copyTargets.clear();
		ghosts.clear();
	}

	/**
	 * Points a click on a copy at the real item's bank slot, so the game withdraws the real item.
	 * Same as core Bank Tags' LayoutManager.onMenuOptionClicked for layout duplicates: only the slot index of
	 * the game's own menu action is changed; no menu entries are added.
	 */
	void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getParam1() == InterfaceID.Bankmain.ITEMS)
		{
			Integer real = copyTargets.get(event.getParam0());
			if (real != null)
			{
				event.getMenuEntry().setParam0(real);
			}
		}
	}

	/**
	 * Gear useful to several styles (barrows gloves, fire cape) lives in one category. Show a faded copy in
	 * each other combat style where it beats everything that style already has in that slot. Copies count too,
	 * so teleport gear copied into its best style (a charged glory in Melee) can reach the others.
	 */
	void addHybridCopies(Map<String, List<Slot>> groups)
	{
		for (String style : Categories.COMBAT_STYLES)
		{
			List<Slot> styleSlots = groups.get(style);
			if (styleSlots == null)
			{
				continue;
			}

			Map<Integer, Integer> bestBySlot = new HashMap<>();
			Set<Integer> shown = new HashSet<>();
			for (Slot s : styleSlots)
			{
				shown.add(s.itemId);
				ItemEquipmentStats e = equipmentOf.apply(s);
				if (e != null)
				{
					bestBySlot.merge(e.getSlot(), GearOrder.score(style, e), Math::max);
				}
			}

			Map<Integer, Slot> candidates = new HashMap<>();
			for (String other : Categories.COMBAT_STYLES)
			{
				if (other.equals(style) || !groups.containsKey(other))
				{
					continue;
				}
				for (Slot s : groups.get(other))
				{
					ItemEquipmentStats e = equipmentOf.apply(s);
					boolean blessing = e != null && e.getSlot() == EquipmentInventorySlot.AMMO.getSlotIdx();
					if (shown.contains(s.itemId) || e == null || e.getSlot() == EquipmentInventorySlot.WEAPON.getSlotIdx()
						|| (!blessing && GearOrder.offence(style, e) <= 0))
					{
						continue;
					}
					int score = GearOrder.score(style, e);
					Slot current = candidates.get(e.getSlot());
					if (score > bestBySlot.getOrDefault(e.getSlot(), 0)
						&& (current == null || score > GearOrder.score(style, equipmentOf.apply(current))))
					{
						candidates.put(e.getSlot(), s);
					}
				}
			}
			for (Slot s : candidates.values())
			{
				styleSlots.add(new Slot(s.widget, s.index, s.itemId, s.quantity, s.name, style, true));
			}
		}
	}

	/**
	 * Items the bundled data lists under extra categories (logs for Firemaking, Graceful for Farming...) get a
	 * withdrawable copy in each of them.
	 */
	void addDataCopies(Map<String, List<Slot>> groups, Predicate<Slot> placedByRule)
	{
		List<Slot> originals = new ArrayList<>();
		groups.values().forEach(list -> list.stream().filter(s -> !s.copy).forEach(originals::add));
		for (Slot s : originals)
		{
			ItemData.Entry data = ItemData.get(s.name);
			// A rule's placement wins. Combat gear can still sit outside its data category: its stats pick the style.
			if (data == null || placedByRule.test(s))
			{
				continue;
			}
			for (String extra : data.extras)
			{
				addCopy(groups, s, extra);
			}
		}
	}

	/**
	 * Items the user also shows in other categories get a withdrawable copy in each of them.
	 */
	void addAlsoShown(Map<String, List<Slot>> groups, Function<Slot, Set<String>> alsoShownIn)
	{
		List<Slot> originals = new ArrayList<>();
		groups.values().forEach(list -> list.stream().filter(s -> !s.copy).forEach(originals::add));
		for (Slot s : originals)
		{
			for (String category : alsoShownIn.apply(s))
			{
				if (!category.equals(s.category))
				{
					addCopy(groups, s, category);
				}
			}
		}
	}

	/**
	 * Items for which {@code show} holds get a withdrawable copy in {@code category}.
	 */
	void addCopies(Map<String, List<Slot>> groups, String category, Predicate<Slot> show)
	{
		List<Slot> originals = new ArrayList<>();
		groups.values().forEach(list -> list.stream().filter(s -> !s.copy && show.test(s)).forEach(originals::add));
		originals.forEach(s -> addCopy(groups, s, category));
	}

	// Unless the category already shows the item.
	private static void addCopy(Map<String, List<Slot>> groups, Slot s, String category)
	{
		List<Slot> target = groups.computeIfAbsent(category, k -> new ArrayList<>());
		if (target.stream().noneMatch(t -> t.itemId == s.itemId))
		{
			target.add(new Slot(s.widget, s.index, s.itemId, s.quantity, s.name, category, true));
		}
	}

	/**
	 * Teleport items that are also combat gear (charged glory, combat bracelet, max cape...) get a copy in
	 * their combat style, where the outfit columns rank them by stats. Only the most-charged version of each
	 * item is copied, so five glories don't fill the amulet row.
	 */
	void addTeleportGearCopies(Map<String, List<Slot>> groups)
	{
		List<Slot> teleports = groups.get(Categories.TELEPORTS);
		if (teleports == null)
		{
			return;
		}

		Map<String, Slot> best = new HashMap<>();
		for (Slot s : teleports)
		{
			ItemEquipmentStats e = equipmentOf.apply(s);
			if (s.copy || e == null || e.getSlot() == EquipmentInventorySlot.WEAPON.getSlotIdx())
			{
				continue;
			}
			best.merge(Doses.baseName(s.name).toLowerCase(), s, (a, b) -> Doses.dose(a.name) >= Doses.dose(b.name) ? a : b);
		}
		for (Slot s : best.values())
		{
			ItemEquipmentStats e = equipmentOf.apply(s);
			String style = Categoriser.gear(s.name.toLowerCase(), e);
			if (Categories.COMBAT_STYLES.contains(style) && GearOrder.offence(style, e) > 0)
			{
				List<Slot> target = groups.computeIfAbsent(style, k -> new ArrayList<>());
				if (target.stream().noneMatch(t -> t.itemId == s.itemId))
				{
					target.add(new Slot(s.widget, s.index, s.itemId, s.quantity, s.name, style, true));
				}
			}
		}
	}

	/**
	 * Draws a copy of {@code slot}'s item in the next spare slot widget, showing the real item's icon and
	 * quantity and carrying its options.
	 *
	 * @return the copy widget, or null when the bank has no spare slots left
	 */
	Widget placeCopy(int index, Slot slot)
	{
		if (index >= spares.size())
		{
			return null;
		}
		Widget real = slot.widget;
		Widget w = spares.get(index);
		w.setItemId(real.getItemId());
		w.setItemQuantity(real.getItemQuantity());
		w.setItemQuantityMode(real.getItemQuantityMode());
		w.setOpacity(real.getOpacity());
		// Item outline and drop shadow, so the copy is drawn exactly like the real item.
		w.setBorderType(real.getBorderType());
		w.setTextShadowed(real.getTextShadowed());
		w.setName(real.getName());
		// Every op, Examine (op 11) included, so the copy's menu is the real item's, Move to and all.
		w.clearActions();
		String[] actions = real.getActions();
		for (int i = 0; actions != null && i < actions.length; i++)
		{
			w.setAction(i, actions[i]);
		}
		w.setDragDeadZone(real.getDragDeadZone());
		w.setDragDeadTime(real.getDragDeadTime());
		w.setHidden(false);
		copyTargets.put(w.getIndex(), slot.index);
		return w;
	}

	/**
	 * Draws a not-owned item in the next spare slot widget exactly as the bank draws a placeholder: the placeholder
	 * item, faded, with a quantity of 0. Unlike a placeholder it gets no options, so the game gives it no menu entries
	 * and a click on it sends nothing; the plugin adds its Release entry itself.
	 *
	 * @param placeholderId the item's placeholder, or -1 if it has none
	 * @return the widget, or null when the bank has no spare slots left
	 */
	Widget placeGhost(int index, Slot slot, int placeholderId)
	{
		if (index >= spares.size())
		{
			return null;
		}
		Widget w = spares.get(index);
		w.setItemId(placeholderId != -1 ? placeholderId : slot.itemId);
		w.setItemQuantity(0);
		w.setItemQuantityMode(ItemQuantityMode.ALWAYS);
		w.setOpacity(PLACEHOLDER_OPACITY);
		w.setBorderType(1);
		w.setTextShadowed(true);
		w.setName("");
		w.clearActions();
		w.setHidden(false);
		ghosts.put(w.getIndex(), slot);
		return w;
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Bundled per-item data, classified from the OSRS Wiki. One line per item:
 * {@code Item name|Main category|Extra categories, comma separated}. Extra categories get withdrawable copies of
 * the item.
 */
final class ItemData
{
	static final class Entry
	{
		final String category;
		final List<String> extras;

		Entry(String category, List<String> extras)
		{
			this.category = category;
			this.extras = extras;
		}
	}

	// A trailing number alone: a charge, dose or level like "(10)" or " 1". Not "(i)", "(broken)" or "(uncharged)".
	// Before ITEMS, which parse() fills using it.
	private static final Pattern NUMBER = Pattern.compile("(\\s*\\(\\d+\\)|\\s+\\d+)$");

	private static final Map<String, Entry> ITEMS = parse(Resources.read("items.txt"));

	private ItemData()
	{
	}

	/**
	 * Reads the bundled data if it hasn't been already. Called at start-up, so that the first bank open doesn't
	 * read it on the client thread.
	 */
	static void load()
	{
		// Initialising the class is what reads it.
	}

	// Trailing variant markers: "(4)", "(i)", "(uncharged)", or a Barrows degrade level like " 75". Not "(unf)": an
	// unfinished potion or bolt isn't a variant of the finished one.
	private static final Pattern VARIANT = Pattern.compile("(\\s*\\((?!unf\\))[^()]*\\)|\\s+\\d+)$");

	/**
	 * Entry for this exact name, else for the name with variant suffixes stripped one at a time, so
	 * "Dharok's helm 75" and "Amulet of glory(4)" find "Dharok's helm" and "Amulet of glory".
	 */
	static Entry get(String name)
	{
		return lookup(ITEMS, name);
	}

	/**
	 * Value for this exact name (lower-case keys), else for the name with variant suffixes stripped one at a time.
	 */
	static <V> V lookup(Map<String, V> byName, String name)
	{
		String n = name.toLowerCase().trim();
		while (true)
		{
			V e = byName.get(n);
			if (e != null)
			{
				return e;
			}
			Matcher m = VARIANT.matcher(n);
			if (!m.find() || m.start() == 0)
			{
				return null;
			}
			n = n.substring(0, m.start()).trim();
		}
	}

	static Map<String, Entry> parse(String text)
	{
		Map<String, Entry> items = new HashMap<>();
		Map<String, Entry> bases = new HashMap<>();
		for (String line : text.split("\\R"))
		{
			String[] parts = line.split("\\|", -1);
			if (line.startsWith("#") || parts.length < 2 || parts[0].trim().isEmpty() || parts[1].trim().isEmpty())
			{
				continue;
			}

			List<String> extras = new ArrayList<>();
			if (parts.length > 2)
			{
				for (String extra : parts[2].split(","))
				{
					if (!extra.trim().isEmpty() && !extra.trim().equals(parts[1].trim()))
					{
						extras.add(extra.trim());
					}
				}
			}
			String name = parts[0].trim().toLowerCase();
			Entry entry = new Entry(parts[1].trim(), Collections.unmodifiableList(extras));
			items.put(name, entry);
			Matcher m = NUMBER.matcher(name);
			if (m.find() && m.start() > 0)
			{
				bases.putIfAbsent(name.substring(0, m.start()).trim(), entry);
			}
		}
		// A numbered entry stands for its siblings: lookup strips "Ardougne cloak 3" and "Black mask (5)" to
		// "ardougne cloak" and "black mask", which find "Ardougne cloak 1" and "Black mask (10)" this way. The first
		// sibling listed wins, and a base name listed itself wins over all of them.
		bases.forEach(items::putIfAbsent);
		return items;
	}
}

package com.smartbanksorter;

import java.util.List;
import java.util.function.Consumer;
import javax.swing.JLabel;

/**
 * What the category editor needs from the game. Item names can only be looked up on the client thread, so answers
 * come back later, on the Swing thread.
 */
interface ItemLookup
{
	final class Row
	{
		// -1 when no item has this name.
		final int itemId;
		final String name;
		// What a rule for this row says: an item name, a wildcard pattern or an ID.
		final String pattern;
		final String detail;
		// The category the item sorts into; null for a pattern or a name no item has.
		final String category;
		final boolean inBank;

		Row(int itemId, String name, String pattern, String detail, String category, boolean inBank)
		{
			this.itemId = itemId;
			this.name = name;
			this.pattern = pattern;
			this.detail = detail;
			this.category = category;
			this.inBank = inBank;
		}
	}

	/**
	 * A row that adds every item a search found as one rule, or null. With a {@code *} it's the search itself;
	 * otherwise every name containing the search, if that's more than one item.
	 *
	 * @param banked the search's items in the bank
	 * @param others the rest of its items
	 */
	static Row patternRow(String text, List<Row> banked, List<Row> others)
	{
		boolean wildcard = text.contains("*");
		int found = banked.size() + others.size();
		// A comma would split the rule in two.
		if (text.contains(",") || !wildcard && found < 2)
		{
			return null;
		}
		String pattern = wildcard ? text : "*" + text + "*";
		int icon = !banked.isEmpty() ? banked.get(0).itemId : !others.isEmpty() ? others.get(0).itemId : -1;
		String detail = "All matches" + (banked.isEmpty() ? "" : " · " + banked.size() + " in your bank");
		return new Row(icon, pattern, pattern, detail, null, !banked.isEmpty());
	}

	/**
	 * Whether a row stands for every item a pattern matches rather than one item and its doses.
	 */
	static boolean isGroup(Row row)
	{
		return isGroup(row.pattern);
	}

	static boolean isGroup(String pattern)
	{
		return pattern.contains("*") && !pattern.endsWith("(*");
	}

	/**
	 * Items whose names contain the text, or match it if it has a {@code *}, the bank's first. Doses and charges of
	 * one item are one row. A row to add them all as one rule, if there is one, comes first.
	 */
	void search(String text, Consumer<List<Row>> done);

	/**
	 * A row to show each rule pattern with, in the same order.
	 */
	void describe(List<String> patterns, Consumer<List<Row>> done);

	void icon(int itemId, JLabel label);
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ColorUtil;

class MoveToMenu
{
	private final Client client;
	private final SmartBankSorterConfig config;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Supplier<List<String>> categoryOrder;

	MoveToMenu(Client client, SmartBankSorterConfig config, ConfigManager configManager, ItemManager itemManager,
		Supplier<List<String>> categoryOrder)
	{
		this.client = client;
		this.config = config;
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.categoryOrder = categoryOrder;
	}

	/**
	 * "Move to" sub-menu on bank items. Picking a category writes a rule to the Custom categories setting, so
	 * one-off fixes don't need a plugin change. Doses and charges are covered by one rule.
	 */
	void addMenu(int itemId)
	{
		String name = itemManager.getItemComposition(itemManager.canonicalize(itemId)).getName();
		String pattern = movePattern(name);
		boolean hasRule = findRule(pattern) >= 0;

		MenuEntry parent = client.getMenu().createMenuEntry(1)
			.setOption("Move to")
			.setTarget(ColorUtil.wrapWithColorTag(name, config.headerColor()))
			.setType(MenuAction.RUNELITE);
		Menu sub = parent.createSubMenu();
		List<String> targets = new ArrayList<>(categoryOrder.get());
		Collections.reverse(targets);
		for (String category : targets)
		{
			sub.createMenuEntry(-1)
				.setOption(category)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> setRule(pattern, category));
		}
		if (hasRule)
		{
			sub.createMenuEntry(-1)
				.setOption("Reset")
				.setTarget(ColorUtil.wrapWithColorTag("automatic", config.headerColor()))
				.setType(MenuAction.RUNELITE)
				.onClick(e -> setRule(pattern, null));
		}
	}

	// "Prayer potion(4)" -> "Prayer potion(*"; other names match exactly.
	static String movePattern(String name)
	{
		return Doses.dose(name) < 0 ? name : name.substring(0, name.lastIndexOf('(')) + "(*";
	}

	/**
	 * Line index of the "Category: pattern" rule written for this exact pattern, or -1.
	 */
	private int findRule(String pattern)
	{
		String[] lines = config.customRules().split("\\R", -1);
		for (int i = 0; i < lines.length; i++)
		{
			int colon = lines[i].indexOf(':');
			if (colon > 0 && lines[i].substring(colon + 1).trim().equalsIgnoreCase(pattern))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Replaces this item's rule with one for {@code category}, or removes it when null. New rules go first so
	 * they win over broader lines the user wrote.
	 */
	private void setRule(String pattern, String category)
	{
		List<String> lines = new ArrayList<>(Arrays.asList(config.customRules().split("\\R", -1)));
		int existing = findRule(pattern);
		if (existing >= 0)
		{
			lines.remove(existing);
		}
		if (category != null)
		{
			lines.add(0, category + ": " + pattern);
		}
		lines.removeIf(String::isEmpty);
		configManager.setConfiguration(SmartBankSorterConfig.GROUP, "customRules", String.join("\n", lines));
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

/**
 * Items the user added to a category but doesn't have. Each shows there drawn and laid out as a placeholder of it, but
 * nothing about it reaches the game: its only option, Release, is the plugin's own. Only single items are shown (a
 * name, an ID, or every dose of one item); a wildcard group would bring in far too many.
 */
final class NotOwnedItems
{
	private final Client client;
	private final ItemManager itemManager;
	// Lower-case pattern -> the item shown for it, -1 for none. Item definitions don't change while the client runs.
	private final Map<String, Integer> resolved = new HashMap<>();

	NotOwnedItems(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/**
	 * Adds a ghost to each category for every single item added there that nothing in the bank matches.
	 *
	 * @param owned the bank's items
	 */
	void addGhosts(Map<String, List<Slot>> groups, UserRules alsoShow, List<Slot> owned)
	{
		Map<String, List<String>> patterns = alsoShow.patterns();
		patterns.values().forEach(this::resolve);
		patterns.forEach((category, list) ->
		{
			for (String pattern : list)
			{
				int id = resolved.getOrDefault(pattern.toLowerCase(), -1);
				if (id < 0 || owned(pattern, owned))
				{
					continue;
				}
				List<Slot> target = groups.computeIfAbsent(category, k -> new ArrayList<>());
				if (target.stream().noneMatch(t -> t.itemId == id))
				{
					target.add(Slot.ghost(id, itemManager.getItemComposition(id).getName(), category, pattern));
				}
			}
		});
	}

	private static boolean owned(String pattern, List<Slot> owned)
	{
		if (pattern.matches("\\d+"))
		{
			int id = Integer.parseInt(pattern);
			return owned.stream().anyMatch(s -> s.itemId == id);
		}
		Pattern glob = UserRules.glob(pattern);
		return owned.stream().anyMatch(s -> glob.matcher(s.name).matches());
	}

	// Finds the item for each new single-item pattern in one pass over the game's items. Of every dose of an item, the
	// most doses or charges.
	private void resolve(List<String> patterns)
	{
		Map<String, Pattern> names = new HashMap<>();
		for (String pattern : patterns)
		{
			String key = pattern.toLowerCase();
			if (resolved.containsKey(key))
			{
				continue;
			}
			if (ItemLookup.isGroup(pattern))
			{
				resolved.put(key, -1);
			}
			else if (pattern.matches("\\d+"))
			{
				int id = Integer.parseInt(pattern);
				resolved.put(key, id < client.getItemCount() ? itemManager.canonicalize(id) : -1);
			}
			else
			{
				names.put(key, UserRules.glob(pattern));
			}
		}
		if (names.isEmpty())
		{
			return;
		}

		Map<String, Integer> best = new HashMap<>();
		Map<String, String> bestName = new HashMap<>();
		for (int id = 0; id < client.getItemCount(); id++)
		{
			ItemComposition item = itemManager.getItemComposition(id);
			String name = item.getName();
			if (item.getNote() != -1 || item.getPlaceholderTemplateId() != -1 || "null".equals(name))
			{
				continue;
			}
			for (Map.Entry<String, Pattern> e : names.entrySet())
			{
				String key = e.getKey();
				if (e.getValue().matcher(name).matches()
					&& (!best.containsKey(key) || Doses.dose(name) > Doses.dose(bestName.get(key))))
				{
					best.put(key, id);
					bestName.put(key, name);
				}
			}
		}
		names.keySet().forEach(key -> resolved.put(key, best.getOrDefault(key, -1)));
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * What an account deposited lately: every item whose stack grew within the window, or only those it has more of now
 * than at the window's start (leftover supplies put back after a trip are fewer than were taken out; loot isn't). Each
 * item's quantity is kept over time, but only while it has changed within the window.
 */
final class RecentDeposits
{
	static final String CATEGORY = "Recently deposited";
	// Enough changes for a week of trips; past this an item's oldest changes are merged into its starting quantity.
	private static final int MAX_CHANGES = 50;

	// Per item, [time, quantity] pairs, oldest first. The first is the quantity before the changes after it, with
	// time 0.
	private final Map<Integer, List<long[]>> history = new HashMap<>();
	// Quantities when the bank was last seen, by item; null until it has been seen since this was loaded. Bank
	// changes made meanwhile (on another client, or with the plugin off) show only for items that have a history.
	private Map<Integer, Long> seen;

	/**
	 * @param saved what {@link #save} returned, or null
	 */
	RecentDeposits(String saved)
	{
		if (saved == null)
		{
			return;
		}
		for (String line : saved.split("\n"))
		{
			String[] parts = line.split("=", 2);
			if (parts.length < 2)
			{
				continue;
			}
			try
			{
				List<long[]> changes = new ArrayList<>();
				for (String change : parts[1].split(","))
				{
					String[] tq = change.split(":");
					changes.add(new long[]{Long.parseLong(tq[0]), Long.parseLong(tq[1])});
				}
				if (changes.size() > 1)
				{
					history.put(Integer.parseInt(parts[0]), changes);
				}
			}
			catch (NumberFormatException | ArrayIndexOutOfBoundsException ignored)
			{
				// A damaged line: forget that item.
			}
		}
	}

	/**
	 * Records the bank's quantities and forgets changes older than the window.
	 *
	 * @param quantities every item in the bank by id, placeholders as 0
	 * @return whether anything to save changed
	 */
	boolean update(Map<Integer, Long> quantities, long now, long window)
	{
		boolean changed = false;
		if (seen == null)
		{
			// The first look since loading: only items with a history can show what changed in between.
			for (Map.Entry<Integer, List<long[]>> e : history.entrySet())
			{
				long quantity = quantities.getOrDefault(e.getKey(), 0L);
				if (latest(e.getValue()) != quantity)
				{
					e.getValue().add(new long[]{now, quantity});
					changed = true;
				}
			}
		}
		else
		{
			Set<Integer> ids = new HashSet<>(seen.keySet());
			ids.addAll(quantities.keySet());
			for (int id : ids)
			{
				long before = seen.getOrDefault(id, 0L);
				long quantity = quantities.getOrDefault(id, 0L);
				if (before != quantity)
				{
					List<long[]> changes = history.computeIfAbsent(id, k ->
					{
						List<long[]> start = new ArrayList<>();
						start.add(new long[]{0, before});
						return start;
					});
					changes.add(new long[]{now, quantity});
					changed = true;
				}
			}
		}
		seen = new HashMap<>(quantities);
		return prune(now - window) || changed;
	}

	/**
	 * Items deposited in the window, each with when it last grew.
	 *
	 * @param netGain only those there are more of now than at the window's start, not supplies taken out and partly
	 *                put back
	 */
	Map<Integer, Long> recent(long now, long window, boolean netGain)
	{
		long start = now - window;
		Map<Integer, Long> recent = new HashMap<>();
		history.forEach((id, changes) ->
		{
			long then = changes.get(0)[1];
			long grew = 0;
			for (int i = 1; i < changes.size(); i++)
			{
				long[] change = changes.get(i);
				if (change[0] <= start)
				{
					then = change[1];
				}
				else if (change[1] > changes.get(i - 1)[1])
				{
					grew = change[0];
				}
			}
			if (grew > 0 && (!netGain || latest(changes) > then))
			{
				recent.put(id, grew);
			}
		});
		return recent;
	}

	String save()
	{
		StringBuilder out = new StringBuilder();
		history.forEach((id, changes) ->
		{
			out.append(id).append('=');
			for (int i = 0; i < changes.size(); i++)
			{
				out.append(i > 0 ? "," : "").append(changes.get(i)[0]).append(':').append(changes.get(i)[1]);
			}
			out.append('\n');
		});
		return out.toString();
	}

	// Folds changes before the window into the starting quantity, and drops items left with nothing after it.
	private boolean prune(long start)
	{
		boolean changed = false;
		for (List<long[]> changes : history.values())
		{
			int keep = 1;
			while (keep < changes.size() && (changes.get(keep)[0] <= start || changes.size() - keep > MAX_CHANGES))
			{
				keep++;
			}
			if (keep > 1)
			{
				long[] first = changes.get(keep - 1);
				changes.subList(0, keep - 1).clear();
				first[0] = 0;
				changed = true;
			}
		}
		changed |= history.values().removeIf(changes -> changes.size() < 2);
		return changed;
	}

	private static long latest(List<long[]> changes)
	{
		return changes.get(changes.size() - 1)[1];
	}
}

package com.smartbanksorter;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class Resources
{
	private Resources()
	{
	}

	/**
	 * @return the text of a data file bundled with the plugin, or "" if it can't be read
	 */
	static String read(String name)
	{
		try (InputStream in = Resources.class.getResourceAsStream(name))
		{
			return in == null ? "" : new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			log.warn("Couldn't read {}", name, e);
			return "";
		}
	}
}

package com.smartbanksorter;

import net.runelite.api.widgets.Widget;

final class Slot
{
	final Widget widget;
	final int index;
	final int itemId;
	final int quantity;
	final String name;
	final String category;
	final boolean copy;
	// An item the user added to a category but doesn't have: drawn as a placeholder, with no widget or bank slot
	// behind it.
	final boolean ghost;
	// For a ghost, the rule that added it; null otherwise.
	final String pattern;

	Slot(Widget widget, int index, int itemId, int quantity, String name, String category)
	{
		this(widget, index, itemId, quantity, name, category, false);
	}

	Slot(Widget widget, int index, int itemId, int quantity, String name, String category, boolean copy)
	{
		this(widget, index, itemId, quantity, name, category, copy, null);
	}

	private Slot(Widget widget, int index, int itemId, int quantity, String name, String category, boolean copy,
		String pattern)
	{
		this.copy = copy;
		this.ghost = pattern != null;
		this.pattern = pattern;
		this.widget = widget;
		this.index = index;
		this.itemId = itemId;
		this.quantity = quantity;
		this.name = name;
		this.category = category;
	}

	/**
	 * A not-owned item to show in {@code category}. It takes a spare slot like a copy does, and is laid out like a
	 * placeholder: an added weapon heads its own outfit. In bank order it goes after the real items.
	 */
	static Slot ghost(int itemId, String name, String category, String pattern)
	{
		return new Slot(null, Integer.MAX_VALUE, itemId, 0, name, category, true, pattern);
	}
}

package com.smartbanksorter;

import java.awt.Color;
import net.runelite.client.config.Config;
