				"Eye of ayak", "Blue moon helm", "Mystic robe bottom", "Blue moon chestplate"));
	}

	private List<List<String>> compact(boolean pack)
	{
		// Scythe (2h, no shield) gets the helm; the whip gets the defender; the dart gets nothing.
		stats.put("Scythe of vitur", melee(EquipmentInventorySlot.WEAPON, 70, 125, 30, 75, 5, true));
		stats.put("Abyssal whip", melee(EquipmentInventorySlot.WEAPON, 0, 82, 0, 82, 4, false));
		stats.put("Rune dart", melee(EquipmentInventorySlot.WEAPON, 0, 0, 0, 0, 3, false));
		stats.put("Torva full helm", melee(EquipmentInventorySlot.HEAD, 0, 0, 0, 8, 0, false));
		stats.put("Dragon defender", melee(EquipmentInventorySlot.SHIELD, 25, 24, 23, 6, 0, false));
		return GearOrder.order(new ArrayList<>(Arrays.asList("Rune dart", "Dragon defender", "Abyssal whip",
			"Torva full helm", "Scythe of vitur")), Categories.MELEE, gear, DpsCalc.Levels.MAXED, Comparator.naturalOrder(),
			true, pack, false, 8);
	}

	@Test
	public void sparseOutfitsGoAfterTheOutfits()
	{
		// The whip would head just the defender and the dart nothing, so both follow the outfits, the defender with
		// the spare gear.
		List<List<String>> expected = Arrays.asList(
			Arrays.asList("Scythe of vitur"),
			Arrays.asList("Torva full helm"),
			Arrays.asList("Abyssal whip", "Rune dart"),
			Arrays.asList("Dragon defender"));
		assertEquals(expected, compact(false));
		assertEquals(expected, compact(true));
	}

	@Test
	public void spareAmmoFollowsWeaponsThatHaveNoOutfit()
	{
		stats.put("Rune crossbow", ItemEquipmentStats.builder().slot(EquipmentInventorySlot.WEAPON.getSlotIdx()).arange(90)
			.aspeed(6).build());
		// A crossbow can't fire arrows.
		stats.put("Rune arrow", ItemEquipmentStats.builder().slot(EquipmentInventorySlot.AMMO.getSlotIdx()).rstr(49).build());
		List<List<String>> order = GearOrder.order(new ArrayList<>(Arrays.asList("Rune arrow", "Rune crossbow")),
			Categories.RANGED, gear, DpsCalc.Levels.MAXED, Comparator.naturalOrder(), true, false, false, 8);
		assertEquals(Arrays.asList(Arrays.asList("Rune crossbow"), Arrays.asList("Rune arrow")), order);
	}

	@Test
	public void weaponsThePlayerCantWieldGoLast()
	{
		stats.put("Scythe of vitur", melee(EquipmentInventorySlot.WEAPON, 70, 125, 30, 75, 5, true));
		stats.put("Abyssal whip", melee(EquipmentInventorySlot.WEAPON, 0, 82, 0, 82, 4, false));
		wieldLevels.put("Scythe of vitur", 80);
		wieldLevels.put("Abyssal whip", 70);
		List<List<String>> order = GearOrder.order(new ArrayList<>(Arrays.asList("Scythe of vitur", "Abyssal whip")),
			Categories.MELEE, gear, new DpsCalc.Levels(75, 99, 99, 99), Comparator.naturalOrder(), true, false, false, 8);
		assertEquals(Arrays.asList(Arrays.asList("Abyssal whip", "Scythe of vitur")), order);
	}

	@Test
	public void untradeableUpgradeBeatsItsBase()
	{
		// Blood fury has fury's stats plus its effect. RuneLite prices it as a fury; without that mapping it's 0.
		add("Amulet of fury", EquipmentInventorySlot.AMULET, 8, 15, 2_000_000);
		add("Amulet of blood fury", EquipmentInventorySlot.AMULET, 8, 15, 2_000_000);
		untradeable.add("Amulet of blood fury");
		assertEquals(Arrays.asList(Arrays.asList("Amulet of blood fury", "Amulet of fury")),
			order(true, "Amulet of fury", "Amulet of blood fury"));
		prices.put("Amulet of blood fury", 0L);
		assertEquals(Arrays.asList(Arrays.asList("Amulet of blood fury", "Amulet of fury")),
			order(true, "Amulet of fury", "Amulet of blood fury"));
	}

	@Test
	public void maxCapeVersionBeatsItsCape()
	{
		add("Infernal cape", EquipmentInventorySlot.CAPE, 8, 12, 0);
		add("Infernal max cape", EquipmentInventorySlot.CAPE, 8, 12, 0);
		untradeable.add("Infernal cape");
		untradeable.add("Infernal max cape");
		assertEquals(Arrays.asList(Arrays.asList("Infernal max cape", "Infernal cape")),
			order(true, "Infernal cape", "Infernal max cape"));
	}

	@Test
	public void equalScoresGoToTheHarderHitter()
	{
		// Both score 300 for Ranged; the hopper's ranged strength beats the book's prayer.
		stats.put("Book of Law", ItemEquipmentStats.builder().slot(EquipmentInventorySlot.SHIELD.getSlotIdx())
			.arange(10).prayer(5).build());
		stats.put("Aquanite hopper", ItemEquipmentStats.builder().slot(EquipmentInventorySlot.SHIELD.getSlotIdx())
			.arange(12).rstr(1).build());
		untradeable.add("Book of Law");
		assertEquals(Arrays.asList(Arrays.asList("Aquanite hopper", "Book of Law")),
			order(Categories.RANGED, true, "Book of Law", "Aquanite hopper"));
	}

	@Test
	public void smallDefenceDifferencesCount()
	{
		ItemEquipmentStats lunar = ItemEquipmentStats.builder().slot(EquipmentInventorySlot.RING.getSlotIdx())
			.amagic(2).dmagic(2).build();
		ItemEquipmentStats beacon = ItemEquipmentStats.builder().slot(EquipmentInventorySlot.RING.getSlotIdx())
			.amagic(2).dmagic(1).build();
		assertTrue(GearOrder.score(Categories.MAGIC, lunar) > GearOrder.score(Categories.MAGIC, beacon));
	}

	@Test
	public void offenceIsPerStyle()
	{
		ItemEquipmentStats barrowsGloves = ItemEquipmentStats.builder().slot(EquipmentInventorySlot.GLOVES.getSlotIdx())
			.astab(12).aslash(12).acrush(12).amagic(6).arange(12).str(12).build();
		ItemEquipmentStats runeKite = ItemEquipmentStats.builder().slot(EquipmentInventorySlot.SHIELD.getSlotIdx())
			.amagic(-8).arange(-2).dstab(35).build();
		assertEquals(6, GearOrder.offence(Categories.MAGIC, barrowsGloves));
		assertEquals(12, GearOrder.offence(Categories.RANGED, barrowsGloves));
		assertEquals(-8, GearOrder.offence(Categories.MAGIC, runeKite));
	}
}

package com.smartbanksorter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class ItemCopiesTest
{
	private final ItemCopies copies = new ItemCopies(s -> null);

	private static Map<String, List<Slot>> bankWith(Slot slot)
	{
		Map<String, List<Slot>> groups = new LinkedHashMap<>();
		groups.put(slot.category, new ArrayList<>());
		groups.get(slot.category).add(slot);
		return groups;
	}

	@Test
	public void copiesWhenStatsPickAnotherStyle()
	{
		// The data says Melee, but the item's stats put it in Ranged.
		Map<String, List<Slot>> groups = bankWith(new Slot(null, 0, 13072, 1, "Elite void robe", Categories.RANGED));
		copies.addDataCopies(groups, s -> false);
		assertEquals(1, groups.get(Categories.RANGED).size());
		assertTrue(groups.get(Categories.MAGIC).get(0).copy);
	}

	@Test
	public void bloodMoonStaysInMelee()
	{
		Map<String, List<Slot>> groups = bankWith(new Slot(null, 0, 29022, 1, "Blood moon chestplate", Categories.MELEE));
		copies.addDataCopies(groups, s -> false);
		assertEquals(1, groups.size());
	}

	@Test
	public void ruleStopsCopies()
	{
		Map<String, List<Slot>> groups = bankWith(new Slot(null, 0, 13072, 1, "Elite void robe", "Void"));
		copies.addDataCopies(groups, s -> true);
		assertEquals(1, groups.size());
	}
}

package com.smartbanksorter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.Map;
import org.junit.Test;

public class ItemDataTest
{
	@Test
	public void variantsFallBackToBaseName()
	{
		// Bundled data has the base names of these.
		assertEquals("Slayer", ItemData.get("Slayer helmet (i)").category);
		assertEquals("Slayer", ItemData.get("Slayer helmet (i) (or)").category);
		assertNull(ItemData.get("Definitely not an item (4)"));
		// Unfinished items aren't variants: these would find Guthix balance(4) and Iron bolts.
		assertNull(ItemData.get("Guthix balance (unf)"));
		assertNull(ItemData.get("Iron bolts (unf)"));
	}

	@Test
	public void numberedEntriesCoverTheirSiblings()
	{
		Map<String, ItemData.Entry> items = ItemData.parse("Ardougne cloak 1|Teleports|\nBlack mask (10)|Slayer|\n"
			+ "Ring of dueling(8)|Teleports|\nRing of dueling(1)|Misc|\nGames necklace|Misc|\n"
			+ "Games necklace(8)|Teleports|\nSaika's hood (broken)|Misc|");
		assertEquals("Teleports", items.get("ardougne cloak").category);
		assertEquals("Slayer", items.get("black mask").category);
		// The first sibling listed wins; a listed base name wins over any sibling.
		assertEquals("Teleports", items.get("ring of dueling").category);
		assertEquals("Misc", items.get("games necklace").category);
		// "(broken)" isn't a number: the real hood mustn't follow the broken one.
		assertNull(items.get("saika's hood"));

		// Through lookup's suffix stripping, with the bundled data.
		assertEquals("Teleports", ItemData.get("Ardougne cloak 4").category);
		assertEquals("Slayer", ItemData.get("Black mask (5)").category);
		assertEquals("Slayer", ItemData.get("Black mask (i)").category);
		assertEquals("Mining", ItemData.get("Varrock armour 3").category);
	}
}

package com.smartbanksorter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class ItemLookupTest
{
	private static ItemLookup.Row item(int id, String name)
	{
		return new ItemLookup.Row(id, name, name, "", "Melee", false);
	}

	private static final List<ItemLookup.Row> BANKED = Collections.singletonList(item(1, "Salve amulet(ei)"));
	private static final List<ItemLookup.Row> OTHERS = Collections.singletonList(item(2, "Salve amulet(i)"));

	@Test
	public void plainSearchOffersEveryNameContainingIt()
	{
		ItemLookup.Row row = ItemLookup.patternRow("salve amulet", BANKED, OTHERS);
		assertEquals("*salve amulet*", row.pattern);
		assertEquals(1, row.itemId);
		assertEquals("All matches · 1 in your bank", row.detail);
		assertTrue(ItemLookup.isGroup(row));
	}

	@Test
	public void plainSearchForOneItemOffersNoGroup()
	{
		assertNull(ItemLookup.patternRow("salve amulet(ei)", BANKED, Collections.emptyList()));
	}

	@Test
	public void wildcardSearchIsAddedAsTyped()
	{
		ItemLookup.Row row = ItemLookup.patternRow("*salve amulet*", Collections.emptyList(), Collections.emptyList());
		assertEquals("*salve amulet*", row.pattern);
		assertEquals("All matches", row.detail);
	}

	@Test
	public void commasWouldSplitTheRule()
	{
		assertNull(ItemLookup.patternRow("a, b*", BANKED, OTHERS));
	}

	@Test
	public void dosesOfOneItemAreNotAGroup()
	{
		assertFalse(ItemLookup.isGroup(new ItemLookup.Row(1, "Prayer potion", "Prayer potion(*", "", null, true)));
		assertFalse(ItemLookup.isGroup(item(1, "Abyssal whip")));
		assertTrue(ItemLookup.isGroup(new ItemLookup.Row(1, "*visage", "*visage", "", null, true)));
	}

	@Test
	public void addingAPatternListsItInTheCategory()
	{
		CategorySettings s = new CategorySettings("", "", "", "", "");
		s.addItem("Bossing", "*salve amulet*");
		assertEquals("Bossing: *salve amulet*", s.rulesText());
		assertEquals(Arrays.asList("*salve amulet*"), s.items("Bossing"));
		assertEquals("Bossing", UserRules.parse(s.rulesText()).match(1, "Salve amulet(ei)"));
	}
}

package com.smartbanksorter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

public class RecentDepositsTest
{
	private static final long HOUR = TimeUnit.HOURS.toMillis(1);
	private static final long WINDOW = 6 * HOUR;
	private static final long T0 = 1_800_000_000_000L;
	private static final int SHARK = 385;
	private static final int WHIP = 4151;
	private static final int BONES = 536;

	private static Map<Integer, Long> bank(Object... idsAndQuantities)
	{
		Map<Integer, Long> bank = new HashMap<>();
		for (int i = 0; i < idsAndQuantities.length; i += 2)
		{
			bank.put((Integer) idsAndQuantities[i], ((Number) idsAndQuantities[i + 1]).longValue());
		}
		return bank;
	}

	@Test
	public void lootShowsButLeftoverSuppliesDoNot()
	{
		RecentDeposits r = new RecentDeposits(null);
		r.update(bank(SHARK, 100, BONES, 10), T0, WINDOW);
		assertTrue("the first look is the starting point", r.recent(T0, WINDOW, true).isEmpty());

		// Take 20 sharks on a trip, come back with 5 and a whip.
		r.update(bank(SHARK, 80), T0 + HOUR, WINDOW);
		r.update(bank(SHARK, 85, WHIP, 1), T0 + 2 * HOUR, WINDOW);
		assertEquals(Collections.singletonMap(WHIP, T0 + 2 * HOUR), r.recent(T0 + 2 * HOUR, WINDOW, true));
	}

	@Test
	public void everyDepositCountsWhenAskedEvenWithMoreTakenOut()
	{
		RecentDeposits r = new RecentDeposits(null);
		r.update(bank(SHARK, 100, BONES, 10), T0, WINDOW);
		// Deposit 200, withdraw 205.
		r.update(bank(SHARK, 300, BONES, 10), T0 + HOUR, WINDOW);
		r.update(bank(SHARK, 95, BONES, 10), T0 + 2 * HOUR, WINDOW);
		assertTrue(r.recent(T0 + 2 * HOUR, WINDOW, true).isEmpty());
		assertEquals(Collections.singletonMap(SHARK, T0 + HOUR), r.recent(T0 + 2 * HOUR, WINDOW, false));
		// A withdrawal alone isn't a deposit.
		r.update(bank(SHARK, 95, BONES, 10), T0 + 3 * HOUR, WINDOW);
		r.update(bank(SHARK, 95, BONES, 5), T0 + 4 * HOUR, WINDOW);
		assertEquals(Collections.singleton(SHARK), r.recent(T0 + 4 * HOUR, WINDOW, false).keySet());
	}

	@Test
	public void depositsDropOffAfterTheWindow()
	{
		RecentDeposits r = new RecentDeposits(null);
		r.update(bank(BONES, 10), T0, WINDOW);
		r.update(bank(BONES, 50), T0 + HOUR, WINDOW);
		assertEquals(Collections.singletonMap(BONES, T0 + HOUR), r.recent(T0 + 6 * HOUR, WINDOW, true));
		assertTrue(r.recent(T0 + 7 * HOUR, WINDOW, true).isEmpty());

		r.update(bank(BONES, 50), T0 + 8 * HOUR, WINDOW);
		assertEquals("nothing left to remember", "", r.save());
	}

	@Test
	public void theLatestDepositDatesTheItem()
	{
		RecentDeposits r = new RecentDeposits(null);
		r.update(bank(BONES, 10), T0, WINDOW);
		r.update(bank(BONES, 50), T0 + HOUR, WINDOW);
		r.update(bank(BONES, 40), T0 + 2 * HOUR, WINDOW);
		r.update(bank(BONES, 70), T0 + 3 * HOUR, WINDOW);
		assertEquals(Collections.singletonMap(BONES, T0 + 3 * HOUR), r.recent(T0 + 3 * HOUR, WINDOW, true));
		// Back to what it was: nothing gained.
		r.update(bank(BONES, 10), T0 + 4 * HOUR, WINDOW);
		assertTrue(r.recent(T0 + 4 * HOUR, WINDOW, true).isEmpty());
	}

	@Test
	public void survivesASaveAndCatchesChangesMadeWhileAway()
	{
		RecentDeposits r = new RecentDeposits(null);
		r.update(bank(BONES, 10, SHARK, 100), T0, WINDOW);
		r.update(bank(BONES, 50, SHARK, 100), T0 + HOUR, WINDOW);

		RecentDeposits loaded = new RecentDeposits(r.save());
		assertEquals(r.recent(T0 + HOUR, WINDOW, true), loaded.recent(T0 + HOUR, WINDOW, true));
		// Logged back in: more bones than last seen counts from now; sharks, with no history, are the new start.
		assertTrue(loaded.update(bank(BONES, 80, SHARK, 150), T0 + 2 * HOUR, WINDOW));
		assertEquals(Collections.singletonMap(BONES, T0 + 2 * HOUR), loaded.recent(T0 + 2 * HOUR, WINDOW, true));
		loaded.update(bank(BONES, 80, SHARK, 160), T0 + 3 * HOUR, WINDOW);
		assertEquals(T0 + 3 * HOUR, (long) loaded.recent(T0 + 3 * HOUR, WINDOW, true).get(SHARK));
	}

	@Test
	public void ignoresDamagedSaves()
	{
		RecentDeposits r = new RecentDeposits("536=0:10,x:50\n4151=0:0," + (T0 + HOUR) + ":1\njunk");
		assertEquals(Collections.singletonMap(WHIP, T0 + HOUR), r.recent(T0 + HOUR, WINDOW, true));
		assertFalse(r.save().contains("536"));
	}

	@Test
	public void longHistoriesAreCapped()
	{
		RecentDeposits r = new RecentDeposits(null);
		r.update(bank(BONES, 0), T0, WINDOW);
		for (int i = 1; i <= 200; i++)
		{
			r.update(bank(BONES, i), T0 + i, WINDOW);
		}
		assertTrue(r.save().split(",").length <= 51);
		assertEquals(T0 + 200, (long) r.recent(T0 + 200, WINDOW, true).get(BONES));
	}
}

