		assertEquals(Arrays.asList("Bossing", "Raids"), new ArrayList<>(alsoShow.matchAll(1, "Salve amulet(ei)")));
		assertEquals(Arrays.asList("Bossing"), new ArrayList<>(alsoShow.matchAll(4081, "Anything")));
